/** @type {null | { prompt: () => Promise<void>; userChoice: Promise<{ outcome: string }> }} */
let deferredInstallPrompt = null;

window.addEventListener("beforeinstallprompt", (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
});

window.addEventListener("appinstalled", () => {
  deferredInstallPrompt = null;
});

function isPhoneHomeStandalone() {
  return (
    window.matchMedia("(display-mode: standalone)").matches ||
    window.matchMedia("(display-mode: fullscreen)").matches ||
    window.matchMedia("(display-mode: minimal-ui)").matches ||
    /** @type {Navigator & { standalone?: boolean }} */ (navigator).standalone === true
  );
}

function isIosBrowser() {
  const ua = navigator.userAgent || "";
  return /iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
}

/**
 * iPhone Safari opened a share link: offer the app before anything redeems the token
 * (Grandma links are one-time). Resolves once the user picks "Continue in Safari".
 */
function offerIosAppHandoff() {
  if (isNativeAppShell() || isPhoneHomeStandalone() || !isIosBrowser()) return Promise.resolve();
  let parsed;
  try {
    parsed = parseMothershipShareInput(LAUNCH_HREF);
  } catch {
    return Promise.resolve();
  }
  if (!parsed.openPath) return Promise.resolve();
  const shareUrl = `${parsed.origin}${parsed.openPath}`;
  try {
    if (sessionStorage.getItem(APP_HANDOFF_DISMISSED_KEY) === shareUrl) return Promise.resolve();
  } catch {
    /* private mode */
  }
  const isGp = Boolean(parsed.gpToken) || parsed.inviteKind === "grandparent";
  const openHref = `phonehome://connect?url=${encodeURIComponent(shareUrl)}`;
  const row = (icon, title, body) => `<li class="app-handoff-why-row">
          <span class="app-handoff-why-icon" aria-hidden="true">${icon}</span>
          <span><strong>${title}</strong><span>${body}</span></span>
        </li>`;
  const svg = (d) =>
    `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
  const ICON_FACE = svg('<circle cx="12" cy="8" r="4"/><path d="M4 21v-1a7 7 0 0 1 16 0v1"/>');
  const ICON_SHIELD = svg('<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/>');
  const ICON_HOME = svg('<path d="M3 11l9-7 9 7"/><path d="M5 10v10h14V10"/><path d="M10 20v-5h4v5"/>');
  const why = isGp
    ? [
        row(ICON_FACE, "Your grandkids call you with one tap", "They see your face on their speed dial — you just answer."),
        row(ICON_SHIELD, "Only family can ring", "No strangers, no sales calls, no public number. Calls are never recorded."),
        row(ICON_HOME, "Nothing to set up", "Your family already did it. Open the app and you’re in — no password to type."),
      ]
    : [
        row(ICON_FACE, "Kids tap a face to call", "Grandparents, cousins, and friends — only the people their parents approve."),
        row(ICON_SHIELD, "No strangers can ring", "No public number or directory. Calls are encrypted and never recorded."),
        row(ICON_HOME, "Free to join", "The family’s private server is already running. You just sign in."),
      ];
  const steps = isGp
    ? ["Get the free PhoneHome app", "Open it — your invite comes along", "You’re signed in. That’s it."]
    : ["Get the free PhoneHome app", "Open it — your invite comes along", "Create your account — you’ll land in the family"];
  const genericTitle = isGp ? "Your family set up a phone for you" : "You’re invited to PhoneHome";
  return new Promise((resolve) => {
    const el = document.createElement("div");
    el.className = "app-handoff";
    el.setAttribute("role", "dialog");
    el.setAttribute("aria-modal", "true");
    el.setAttribute("aria-labelledby", "app-handoff-title");
    el.innerHTML = `
      <div class="app-handoff-card">
        <img class="app-handoff-icon" src="/apple-touch-icon.png" width="64" height="64" alt="" />
        <p class="app-handoff-kicker">You’re invited</p>
        <h2 id="app-handoff-title">${genericTitle}</h2>
        <p class="app-handoff-lede">PhoneHome is a private phone line for families — like the old kitchen phone, but only your people can call.</p>
        <ul class="app-handoff-why">${why.join("")}</ul>
        <div class="app-handoff-steps">
          <p class="app-handoff-steps-title">How to accept</p>
          <ol>${steps.map((s) => `<li>${s}</li>`).join("")}</ol>
        </div>
        <button type="button" class="primary btn-block" id="app-handoff-get">Get the free app</button>
        <a class="ghost btn-block" id="app-handoff-open" href="${openHref}">I have the app — open my invite</a>
        <p class="tiny app-handoff-note" id="app-handoff-note" hidden>Invite link copied. After installing, open PhoneHome and tap <strong>Paste copied invite link</strong>.</p>
        <button type="button" class="linkish" id="app-handoff-web">Continue in Safari instead</button>
      </div>`;
    document.body.appendChild(el);
    if (parsed.joinToken) {
      void fetch(`${parsed.origin}/api/join/peek?token=${encodeURIComponent(parsed.joinToken)}`)
        .then((r) => (r.ok ? r.json() : null))
        .then((peek) => {
          const title = el.querySelector("#app-handoff-title");
          if (!peek || !title) return;
          const clean = (s) => String(s || "").replace(/[<>&"]/g, "").trim();
          const who = clean(peek.inviterGivenName);
          const family = clean(peek.fromHouseholdName);
          const kid = clean(peek.targetKidLabel);
          const familyLabel = family && family !== "A family" ? `the ${family} family` : "their family";
          if (peek.kind === "guardian" && kid) {
            title.textContent = `${who || "A parent"} invited you to help parent ${kid}`;
          } else if (peek.kind === "friend" && kid) {
            title.textContent = `${who || "A parent"} invited your family to call ${kid}`;
          } else {
            title.textContent = `${who || "Someone"} invited you to ${familyLabel}`;
          }
        })
        .catch(() => {});
    }
    el.querySelector("#app-handoff-get")?.addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(shareUrl);
        el.querySelector("#app-handoff-note")?.removeAttribute("hidden");
      } catch {
        /* clipboard blocked — still send them to install */
      }
      setTimeout(() => {
        window.location.href = PHONEHOME_IOS_APP_URL;
      }, 900);
    });
    el.querySelector("#app-handoff-web")?.addEventListener("click", () => {
      try {
        sessionStorage.setItem(APP_HANDOFF_DISMISSED_KEY, shareUrl);
      } catch {
        /* private mode */
      }
      el.remove();
      resolve();
    });
  });
}

const APP_BANNER_DISMISSED_KEY = "ph_ios_app_banner_dismissed_at";
const APP_BANNER_SNOOZE_MS = 14 * 24 * 60 * 60 * 1000;

/**
 * iPhone/iPad Safari on a Mothership web app: slim top bar to get or open the app.
 * Swap for Apple's Smart App Banner (apple-itunes-app meta) once the app is public on the App Store.
 */
function mountIosAppBanner() {
  if (isNativeAppShell() || isPhoneHomeStandalone() || !isIosBrowser()) return;
  if (isLocalMothershipOperatorUi()) return;
  if (document.querySelector(".ios-app-banner")) return;
  let target = location.origin;
  let isInvite = false;
  try {
    const parsed = parseMothershipShareInput(LAUNCH_HREF);
    if (parsed.openPath) {
      target = `${parsed.origin}${parsed.openPath}`;
      isInvite = true;
    }
  } catch {
    /* plain Mothership page */
  }
  // A fresh invite is a first impression — show the bar even if it was snoozed on a plain visit.
  if (!isInvite) {
    try {
      const at = Number(localStorage.getItem(APP_BANNER_DISMISSED_KEY) || 0);
      if (at && Date.now() - at < APP_BANNER_SNOOZE_MS) return;
    } catch {
      /* private mode */
    }
  }
  const bar = document.createElement("div");
  bar.className = "ios-app-banner";
  bar.setAttribute("role", "region");
  bar.setAttribute("aria-label", "PhoneHome iPhone app");
  bar.innerHTML = `
    <button type="button" class="ios-app-banner-close" aria-label="Dismiss">×</button>
    <img class="ios-app-banner-icon" src="/apple-touch-icon.png" width="40" height="40" alt="" />
    <span class="ios-app-banner-copy">
      <strong>PhoneHome for iPhone</strong>
      <span>Free · calls ring on your lock screen</span>
    </span>
    <span class="ios-app-banner-actions">
      <a class="ios-app-banner-get" href="${PHONEHOME_IOS_APP_URL}" target="_blank" rel="noopener noreferrer">Get</a>
      <a class="ios-app-banner-open" href="phonehome://connect?url=${encodeURIComponent(target)}">Have it? Open</a>
    </span>`;
  bar.querySelector(".ios-app-banner-close")?.addEventListener("click", () => {
    try {
      localStorage.setItem(APP_BANNER_DISMISSED_KEY, String(Date.now()));
    } catch {
      /* private mode */
    }
    bar.remove();
    document.documentElement.classList.remove("has-ios-app-banner");
  });
  const root = document.getElementById("app");
  if (root) root.before(bar);
  else document.body.prepend(bar);
  document.documentElement.classList.add("has-ios-app-banner");
}

/** iOS app shell: no pinch/double-tap zoom and no auto-zoom into small inputs (web keeps zoom for WCAG). */
function lockNativeViewportZoom() {
  if (!isNativeAppShell()) return;
  const meta = document.querySelector('meta[name="viewport"]');
  if (!meta) return;
  meta.setAttribute(
    "content",
    "width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover"
  );
}

const SITE_LEGAL_PAGES = new Set(["privacy.html", "support.html", "terms.html", "refund.html"]);
/** Checkout stays in Safari (App Store–safe link-out); everything else on the site opens in-app. */
const SITE_SAFARI_ONLY = /^\/(buy|trial|buy-success)(\.html)?$/i;

/** PhoneHome site URL for an in-app sheet, or "" when the link should keep its normal behavior. */
function inAppSiteUrl(href) {
  const raw = String(href || "").trim();
  if (!raw || raw.startsWith("#")) return "";
  let url;
  try {
    url = new URL(raw, location.href);
  } catch {
    return "";
  }
  // Parent / Profile section chips (#parent-kids, etc.) — not storefront pages.
  if (
    url.origin === location.origin &&
    url.pathname === location.pathname &&
    url.search === location.search
  ) {
    return "";
  }
  const file = url.pathname.replace(/^\//, "");
  if (url.origin === location.origin && SITE_LEGAL_PAGES.has(file)) {
    return storefrontPageUrl(file);
  }
  let siteHost = "phonehome.pages.dev";
  try {
    siteHost = new URL(storefrontPageUrl("")).host;
  } catch {
    /* default host */
  }
  if (url.protocol !== "https:") return "";
  if (url.host !== siteHost && url.host !== "phonehome.pages.dev") return "";
  if (SITE_SAFARI_ONLY.test(url.pathname)) return "";
  return url.toString();
}

/** iOS app: PhoneHome site pages open in SFSafariViewController (Done + back/forward). */
function bindInAppSiteLinks() {
  if (!isNativeAppShell()) return;
  document.addEventListener(
    "click",
    (e) => {
      const link = e.target instanceof Element ? e.target.closest("a[href]") : null;
      if (!link) return;
      const target = inAppSiteUrl(link.getAttribute("href") || "");
      const kit = nativePlugin();
      if (!target || typeof kit?.openInAppBrowser !== "function") return;
      e.preventDefault();
      e.stopPropagation();
      void Promise.resolve(kit.openInAppBrowser({ url: target })).catch(() => {
        window.open(target, "_blank", "noopener");
      });
    },
    true
  );
}

function isNativeAppShell() {
  try {
    return Boolean(window.Capacitor?.isNativePlatform?.());
  } catch {
    return false;
  }
}

/**
 * Capacitor / in-app WebViews ignore `<a download>`, and iOS WKWebView often
 * rejects `navigator.share({ files })` with NotAllowedError even when
 * `canShare` is true. On native, open the authenticated URL in Safari so the
 * parent can Save to Files from there.
 * @returns {"shared" | "browser" | "download"}
 */
let pendingNativeViewportRepair = { current: false };

/**
 * Present the OS share sheet for plain text (invite / Grandma / co-parent).
 *
 * Cap iOS / WKWebView often never settles `navigator.share` after the user
 * picks Messages (app backgrounds). Racing on return keeps Parent from hanging
 * forever behind that await. Also arms viewport repair — share handoff can leave
 * the same scroll/zoom mess as Safari ATA downloads.
 *
 * Important: call `navigator.share` synchronously from the tap handler (no await
 * before it) or Cap/Safari drop the user gesture.
 *
 * Passes `url` separately (extracted from text when needed) so iMessage can show
 * the rich preview image. The same URL is stripped from `text` to avoid
 * duplicate link lines in Messages.
 *
 * @returns {Promise<"shared" | "aborted" | "unsupported">}
 */
async function sharePlainText({ title, text, url } = {}) {
  if (typeof navigator.share !== "function") return "unsupported";
  const body = String(text || "");
  const link = String(url || "").trim() || extractHttpsUrlFromText(body);
  if (!body && !link) return "unsupported";
  if (isNativeAppShell()) pendingNativeViewportRepair.current = true;

  /** @type {ShareData} */
  const payload = { title: title || "PhoneHome" };
  if (link) {
    payload.url = link;
    const caption = textForShareWithUrl(body, link);
    if (caption) payload.text = caption;
  } else {
    payload.text = body;
  }

  let leftForShare = false;
  const markLeft = () => {
    leftForShare = true;
  };
  const onVisLeave = () => {
    if (document.hidden) markLeft();
  };
  document.addEventListener("visibilitychange", onVisLeave);

  /** @type {{ remove: () => void } | null} */
  let capLeaveSub = null;
  /** @type {{ remove: () => void } | null} */
  let capResumeSub = null;
  let onVisBack = null;
  const CapApp = window.Capacitor?.Plugins?.App;
  // Do not await Cap listeners before share — that burns the user gesture.
  void CapApp?.addListener?.("appStateChange", (ev) => {
    if (ev?.isActive === false) markLeft();
  })
    .then((sub) => {
      capLeaveSub = sub;
    })
    .catch(() => {});

  // Must stay sync with the calling tap — first await is this promise.
  const shareP = navigator.share(payload).then(
    () => "shared",
    (err) => {
      if (err?.name === "AbortError") {
        // Some iOS builds abort the promise when Messages opens — still a success.
        return leftForShare ? "shared" : "aborted";
      }
      throw err;
    }
  );

  // Unstick when we return from Messages / Mail if shareP never settles.
  const resumeP = new Promise((resolve) => {
    let settled = false;
    const finish = () => {
      if (settled || !leftForShare) return;
      settled = true;
      teardownResume();
      setTimeout(() => resolve("shared"), 120);
    };
    onVisBack = () => {
      if (!document.hidden && leftForShare) finish();
    };
    document.addEventListener("visibilitychange", onVisBack);
    void CapApp?.addListener?.("appStateChange", (ev) => {
      if (ev?.isActive && leftForShare) finish();
    })
      .then((sub) => {
        capResumeSub = sub;
      })
      .catch(() => {});
  });

  const teardownResume = () => {
    if (onVisBack) document.removeEventListener("visibilitychange", onVisBack);
    onVisBack = null;
    try {
      capResumeSub?.remove?.();
    } catch {
      /* ignore */
    }
    capResumeSub = null;
  };

  try {
    return await Promise.race([shareP, resumeP]);
  } finally {
    document.removeEventListener("visibilitychange", onVisLeave);
    try {
      capLeaveSub?.remove?.();
    } catch {
      /* ignore */
    }
    teardownResume();
    void shareP.catch(() => {});
  }
}

async function offerDownloadedFile(blob, filename, openUrlPath) {
  if (isNativeAppShell() && openUrlPath) {
    const abs = new URL(openUrlPath, window.location.href).href;
    const CapApp = window.Capacitor?.Plugins?.App;
    pendingNativeViewportRepair.current = true;
    if (typeof CapApp?.openUrl === "function") {
      await CapApp.openUrl({ url: abs });
      return "browser";
    }
    window.open(abs, "_blank", "noopener");
    return "browser";
  }

  const mime =
    blob.type ||
    (filename.endsWith(".txt") ? "text/plain" : filename.endsWith(".cfg") ? "text/plain" : "application/xml");
  const fileObj = new File([blob], filename, { type: mime });
  const sharePayload = { files: [fileObj], title: filename };

  // Mobile Safari (not Cap): share sheet → Save to Files when the platform allows it.
  if (typeof navigator.canShare === "function" && navigator.canShare(sharePayload)) {
    try {
      await navigator.share(sharePayload);
      return "shared";
    } catch (err) {
      if (err?.name === "AbortError") throw err;
      /* fall through to anchor download */
    }
  }

  const href = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = href;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(href), 2000);
  return "download";
}

/** After Safari/Files handoff, WKWebView can leave scroll/zoom under the status bar. */
function repairNativeShellViewport() {
  if (!isNativeAppShell()) return;
  try {
    document.activeElement?.blur?.();
  } catch {
    /* ignore */
  }
  const snapTop = () => {
    scrollPageToTop();
  };
  snapTop();
  requestAnimationFrame(() => {
    snapTop();
    // Nudge layout so env(safe-area-inset-*) re-evaluates.
    const html = document.documentElement;
    html.style.setProperty("--ph-viewport-nudge", "0.01px");
    requestAnimationFrame(() => {
      html.style.removeProperty("--ph-viewport-nudge");
      snapTop();
    });
  });
}

/** PWA home-screen icon or native Capacitor shell — not a Safari/Chrome tab. */
function isInstalledPhoneHome() {
  return isPhoneHomeStandalone() || isNativeAppShell();
}

function hasCompletedHowItWorksInstall() {
  try {
    return localStorage.getItem(HOW_IT_WORKS_INSTALL_KEY) === "1";
  } catch {
    return false;
  }
}

/**
 * First launch of this native app / installed PWA that has not finished How it works.
 * Existing WebView installs that already set TUTORIAL_KEY are not re-trapped.
 */
function mustCompleteHowItWorks() {
  // Operator claiming a fresh Mothership locally — skip the phone product tour.
  if (state.mothershipBootstrap && state.mothershipBootstrap.initialized === false) {
    if (isLocalMothershipOperatorUi()) return false;
  }
  if (!isInstalledPhoneHome()) return false;
  if (hasCompletedHowItWorksInstall()) return false;
  try {
    if (localStorage.getItem(TUTORIAL_KEY) === "1") return false;
  } catch {
    /* ignore */
  }
  return true;
}

/** Dashboard opened on the box itself (127.0.0.1) or via Mac app ?host=1. */
function isLocalMothershipOperatorUi() {
  try {
    const host = location.hostname;
    if (host === "127.0.0.1" || host === "localhost" || host === "[::1]") return true;
  } catch {
    /* ignore */
  }
  try {
    return new URLSearchParams(location.search).get("host") === "1";
  } catch {
    return false;
  }
}

async function loadMothershipBootstrap() {
  try {
    const data = await fetch("/api/bootstrap", { credentials: "same-origin" }).then((r) => r.json());
    state.mothershipBootstrap = data;
    if (data?.license) state.hostLicense = data.license;
    return data;
  } catch {
    state.mothershipBootstrap = null;
    return null;
  }
}

/** Forced first-install run — not Help / welcome replay. */
function isForcedHowItWorksRun() {
  return mustCompleteHowItWorks() && !state.tutorialFromSettings;
}

function startForcedHowItWorks({ fromSplash = false } = {}) {
  state.tutorialFromSettings = false;
  state.tutorialIndex = fromSplash ? 1 : 0;
  state.tutorialFarthest = state.tutorialIndex;
  state.screen = "tutorial";
}

/** Pull device-scoped How it works completion into this origin’s localStorage. */
async function applyNativeOnboardingFlags() {
  if (!isNativeAppShell()) return;
  const kit = await nativePluginReady(800);
  if (!kit?.getOnboarding) return;
  try {
    const res = await kit.getOnboarding();
    if (!res?.howItWorksDone) return;
    localStorage.setItem(TUTORIAL_KEY, "1");
    localStorage.setItem(HOW_IT_WORKS_INSTALL_KEY, "1");
  } catch {
    /* ignore */
  }
}

/** Mark How it works done here and on-device (survives Cap → hub hop). */
async function persistHowItWorksDoneToDevice() {
  try {
    localStorage.setItem(TUTORIAL_KEY, "1");
    localStorage.setItem(HOW_IT_WORKS_INSTALL_KEY, "1");
  } catch {
    /* private mode */
  }
  if (!isNativeAppShell()) return;
  const kit = await nativePluginReady(800);
  try {
    await kit?.setOnboarding?.({ howItWorksDone: true });
  } catch {
    /* ignore */
  }
}

/** Cap bundled shell still needs a Mothership before Sign in. */
function shouldConnectMothershipAfterTutorial() {
  return Boolean(
    state.pendingMothershipConnect || (isNativeAppShell() && isBundledCapOrigin())
  );
}

const LAST_USERNAME_KEY = "kl_username";
/** One Face ID auto-prompt per WebView lifetime (avoid re-prompt loops on error). */
let faceIdAutoTried = false;

/** Native Capacitor plugin (CallKit + Keychain). Remote WebView talks via jsName. */
function nativePlugin() {
  try {
    const plugins = window.Capacitor?.Plugins;
    if (plugins?.PhoneHomeCallKit) return plugins.PhoneHomeCallKit;
  } catch {
    /* ignore */
  }
  try {
    return window.Capacitor?.registerPlugin?.("PhoneHomeCallKit") || null;
  } catch {
    return null;
  }
}

async function nativePluginReady(ms = 1200) {
  const start = Date.now();
  let plugin = nativePlugin();
  while (!plugin?.saveLogin && !plugin?.hasSavedLogin && Date.now() - start < ms) {
    await new Promise((r) => setTimeout(r, 50));
    plugin = nativePlugin();
  }
  return plugin;
}

/** Cap bundled assets (capacitor:// or localhost) — not yet on a remote Mothership. */
function isBundledCapOrigin() {
  try {
    const proto = String(location.protocol || "").toLowerCase();
    if (proto === "capacitor:" || proto === "ionic:") return true;
    const host = String(location.hostname || "").toLowerCase();
    return host === "localhost" || host === "127.0.0.1" || host === "";
  } catch {
    return false;
  }
}

function normalizeMothershipUrlInput(raw) {
  return parseMothershipShareInput(raw).origin;
}

/** Native WKWebView often blocks navigator.clipboard — use plugin when available. */
async function readClipboardText() {
  try {
    const kit = await nativePluginReady(600);
    if (kit?.readClipboard) {
      const res = await kit.readClipboard();
      const text = String(res?.text || "").trim();
      if (text) return text;
    }
  } catch {
    /* fall through */
  }
  try {
    const text = await navigator.clipboard.readText();
    return String(text || "").trim();
  } catch {
    return "";
  }
}

async function getSavedMothershipUrl() {
  const kit = await nativePluginReady(800);
  if (!kit?.getMothershipUrl) return "";
  try {
    const res = await kit.getMothershipUrl();
    return String(res?.url || "").trim();
  } catch {
    return "";
  }
}

async function probeMothershipHealth(origin, ms = 8000) {
  const base = String(origin || "").replace(/\/$/, "");
  if (!base) return false;
  const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
  const t = setTimeout(() => ctrl?.abort(), ms);
  try {
    const r = await fetch(`${base}/api/health`, {
      method: "GET",
      credentials: "omit",
      signal: ctrl?.signal,
    });
    return r.ok;
  } catch {
    return false;
  } finally {
    clearTimeout(t);
  }
}

/**
 * Native shell only. Returns 'ok' | 'gate' | 'reloading'.
 * Shows gate when no saved URL (bundled) or hub health check fails.
 */
async function ensureMothershipUrlReady() {
  if (!isNativeAppShell()) return "ok";
  const kit = await nativePluginReady(1500);
  void loadAppStorefront(kit);
  let saved = await getSavedMothershipUrl();

  // Persist current https origin if native store is empty (upgrade / baked server.url).
  if (!saved && location.protocol === "https:" && !isBundledCapOrigin()) {
    try {
      await kit?.setMothershipUrl?.({ url: location.origin, reload: false });
      saved = location.origin;
    } catch {
      /* ignore */
    }
  }

  const onBundled = isBundledCapOrigin();
  if (!saved && onBundled) return "gate";

  const base = saved || (location.protocol === "https:" ? location.origin : "");
  if (!base) return onBundled ? "gate" : "ok";

  const ok = await probeMothershipHealth(base);
  if (!ok) return "gate";

  if (onBundled && saved && kit?.setMothershipUrl) {
    try {
      await kit.setMothershipUrl({ url: saved, reload: true });
      return "reloading";
    } catch {
      return "gate";
    }
  }
  return "ok";
}

function originOf(url) {
  try {
    return new URL(String(url || "")).origin;
  } catch {
    return "";
  }
}

async function consumeNativeInviteLink() {
  const kit = await nativePluginReady(1500);
  if (!kit?.consumeInviteLink) return "";
  try {
    return String((await kit.consumeInviteLink())?.url || "").trim();
  } catch {
    return "";
  }
}

let nativeInviteLinkListenerBound = false;
function bindNativeInviteLinkListener() {
  if (nativeInviteLinkListenerBound) return;
  const kit = nativePlugin();
  if (!kit?.addListener || !kit?.consumeInviteLink) return;
  nativeInviteLinkListenerBound = true;
  void kit.addListener("inviteLink", async () => {
    const url = await consumeNativeInviteLink();
    if (url) await handleNativeInviteLink(url);
  });
}

function showMothershipGateWithInvite(url, flash, tone = "ok") {
  state.mothershipUrlChanging = false;
  state.pendingMothershipConnect = true;
  state.mothershipUrlFromOnboarding = true;
  state.mothershipUrlDraft = url;
  state.mothershipPath = "join";
  const el = document.getElementById("mothership-url");
  if (el) el.value = url;
  state.screen = "mothership-url";
  setFlash(flash, tone);
  render();
}

/**
 * Native: share link from the Mothership page's "Open in the app" (`phonehome://connect?url=`).
 * New installs get Connect prefilled (one tap); a different saved hub asks before switching.
 * Returns true when it took over the screen or reloaded the WebView.
 */
async function handleNativeInviteLink(url) {
  let parsed;
  try {
    parsed = parseMothershipShareInput(url);
  } catch {
    return false;
  }
  const saved = originOf(await getSavedMothershipUrl());
  const current = isBundledCapOrigin() ? "" : location.origin;
  const hub = saved || current;
  if (!hub) {
    showMothershipGateWithInvite(url, "Invite link filled in — tap Connect & continue");
    return true;
  }
  if (hub !== parsed.origin) {
    const host = new URL(parsed.origin).host;
    const ok = confirm(
      `This invite is for a different Mothership (${host}).\n\nSwitch to it? You can change back later in Parent → Mothership.`
    );
    if (!ok) return false;
  }
  try {
    await connectMothershipUrl(url);
  } catch (e) {
    showMothershipGateWithInvite(url, e?.message || "Couldn’t reach that Mothership", "error");
  }
  return true;
}

async function connectMothershipUrl(raw) {
  const parsed = parseMothershipShareInput(raw);
  const url = parsed.origin;
  // Stash tokens before the WebView hops hubs (bundled sessionStorage won't follow).
  if (parsed.joinToken) setPendingJoinToken(parsed.joinToken);
  if (parsed.gpToken) setPendingGrandparentSetupToken(parsed.gpToken);
  if (parsed.inviteCode) {
    setPendingFamilyInvite(parsed.inviteCode, parsed.inviteKind);
    state.familyInviteOffer = true;
  }
  const ok = await probeMothershipHealth(url);
  if (!ok) {
    throw new Error("Couldn’t reach that Mothership — check the address and that you’re online");
  }
  const kit = await nativePluginReady(1500);
  if (!kit?.setMothershipUrl) {
    // Browser / web stub — navigate directly (preserve share path when present).
    window.location.href = parsed.openPath ? `${url}${parsed.openPath}` : url;
    return url;
  }
  await kit.setMothershipUrl({
    url,
    reload: true,
    ...(parsed.openPath ? { openPath: parsed.openPath } : {}),
  });
  return url;
}

function lastUsername() {
  try {
    return localStorage.getItem(LAST_USERNAME_KEY) || "";
  } catch {
    return "";
  }
}

function rememberUsername(username) {
  const u = String(username || "").trim();
  try {
    if (u) localStorage.setItem(LAST_USERNAME_KEY, u);
    else localStorage.removeItem(LAST_USERNAME_KEY);
  } catch {
    /* ignore quota / private mode */
  }
}

async function persistSession(sessionId) {
  state.sessionId = sessionId || "";
  try {
    if (sessionId) localStorage.setItem("kl_session", sessionId);
    else localStorage.removeItem("kl_session");
  } catch {
    /* ignore */
  }
  const plugin = nativePlugin();
  try {
    if (!plugin) return;
    if (sessionId) await plugin.saveSession?.({ sessionId });
    else await plugin.clearSession?.();
  } catch {
    /* Keychain optional until the iOS shell is rebuilt */
  }
}

async function persistPasswordLogin(username, password) {
  rememberUsername(username);
  const plugin = await nativePluginReady();
  if (!plugin?.saveLogin) {
    console.warn("[ios] saveLogin missing — rebuild the PhoneHome app for Face ID");
    return false;
  }
  const user = String(username || "").trim();
  const pass = String(password || "");
  if (!user || !pass) return false;
  try {
    const out = await plugin.saveLogin({ username: user, password: pass });
    if (out && out.saved === false) {
      console.warn("[ios] saveLogin returned saved:false");
      return false;
    }
    const check = await plugin.hasSavedLogin?.();
    if (check && check.saved === false) {
      console.warn("[ios] Keychain has no password after saveLogin");
      return false;
    }
    return true;
  } catch (e) {
    console.warn("[ios] saveLogin failed", e);
    return false;
  }
}

async function clearPersistedAuth({ keepLogin = false } = {}) {
  await persistSession("");
  if (keepLogin) return;
  rememberUsername("");
  const plugin = nativePlugin();
  try {
    await plugin?.clearLogin?.();
  } catch {
    /* ignore */
  }
}

async function restoreNativeSession() {
  if (state.sessionId) {
    void persistSession(state.sessionId);
    return;
  }
  const plugin = nativePlugin();
  try {
    const out = await plugin?.getSession?.();
    const sid = String(out?.sessionId || "");
    if (sid) {
      state.sessionId = sid;
      try {
        localStorage.setItem("kl_session", sid);
      } catch {
        /* ignore */
      }
    }
  } catch {
    /* ignore */
  }
}

function isUnauthorizedError(err) {
  return Number(err?.status) === 401;
}

document.documentElement.classList.toggle("ph-standalone", isPhoneHomeStandalone());

function getUiTheme() {
  const t = localStorage.getItem(UI_THEME_KEY) || "modern";
  return UI_THEME_IDS.has(t) ? t : "modern";
}

function uiThemeLabel(theme = getUiTheme()) {
  return UI_THEME_META[theme]?.label || "Modern";
}

function applyUiTheme(theme) {
  const t = UI_THEME_IDS.has(theme) ? theme : "modern";
  document.documentElement.dataset.theme = t;
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.content = UI_THEME_COLORS[t] || UI_THEME_COLORS.modern;
}

function setUiTheme(theme) {
  const t = UI_THEME_IDS.has(theme) ? theme : "modern";
  localStorage.setItem(UI_THEME_KEY, t);
  applyUiTheme(t);
  refreshAvatarPalettes();
}

applyUiTheme(getUiTheme());

function getA11yPrefs() {
  try {
    const raw = localStorage.getItem(A11Y_KEY);
    if (!raw) return { ...A11Y_DEFAULTS };
    const parsed = JSON.parse(raw);
    return {
      text: ["default", "large", "xlarge"].includes(parsed?.text) ? parsed.text : A11Y_DEFAULTS.text,
      motion: ["system", "reduce", "full"].includes(parsed?.motion)
        ? parsed.motion
        : A11Y_DEFAULTS.motion,
      targets: Boolean(parsed?.targets),
      links: Boolean(parsed?.links),
      focus: Boolean(parsed?.focus),
    };
  } catch {
    return { ...A11Y_DEFAULTS };
  }
}

function applyA11yPrefs(prefs = getA11yPrefs()) {
  const root = document.documentElement;
  root.dataset.a11yText = prefs.text;
  root.dataset.a11yMotion = prefs.motion;
  root.dataset.a11yTargets = prefs.targets ? "1" : "0";
  root.dataset.a11yLinks = prefs.links ? "1" : "0";
  root.dataset.a11yFocus = prefs.focus ? "1" : "0";
}

function setA11yPrefs(patch) {
  const next = { ...getA11yPrefs(), ...patch };
  localStorage.setItem(A11Y_KEY, JSON.stringify(next));
  applyA11yPrefs(next);
  return next;
}

function a11ySummaryLabel(prefs = getA11yPrefs()) {
  const bits = [];
  if (prefs.text === "large") bits.push("Large text");
  else if (prefs.text === "xlarge") bits.push("Extra-large text");
  if (prefs.motion === "reduce") bits.push("Less motion");
  if (prefs.targets) bits.push("Bigger taps");
  if (prefs.links) bits.push("Underlined links");
  if (prefs.focus) bits.push("Strong focus");
  if (!bits.length) return "Default";
  return bits.slice(0, 2).join(" · ") + (bits.length > 2 ? "…" : "");
}

applyA11yPrefs();

/** Themes shown in a picker — full list, or age-friendly subset for grandparent accounts. */
function themesForPicker(opts = {}) {
  if (!opts.grandparent) return UI_THEMES;
  const curated = UI_THEME_IDS_GRANDPARENT.map((id) => UI_THEME_META[id]).filter(Boolean);
  const current = getUiTheme();
  if (!UI_THEME_IDS_GRANDPARENT.includes(current) && UI_THEME_META[current]) {
    return [...curated, UI_THEME_META[current]];
  }
  return curated;
}

/**
 * Theme picker.
 * Post-login: setup board (optional) + Parent → Themes + grandparent Settings.
 * How it works includes a tap-to-try slide. Splash stays brand-only.
 */
function uiThemeSelectorHtml(opts = {}) {
  const { bare = false, setup = false, grandparent = false } = opts;
  const current = getUiTheme();
  const themes = themesForPicker({ grandparent });
  const grid = `
      <div class="theme-grid${grandparent ? " gp-theme-grid" : ""}" role="group" aria-label="${
        grandparent ? "How it looks" : "Themes"
      }">
        ${themes
          .map(
            ({ id, label, detail }) =>
              `<button type="button" class="theme-opt ${current === id ? "on" : ""}" data-ui-theme="${id}" aria-pressed="${current === id}">
              <span class="theme-swatch theme-swatch-${id}" aria-hidden="true"></span>
              <strong>${label}</strong>
              <span>${detail}</span>
            </button>`
          )
          .join("")}
      </div>`;
  if (bare) return grid;
  let wrapCls = "parent-field ui-theme-field";
  let headTag = "h3";
  let headCls = "parent-subhead";
  let lede =
    "How PhoneHome looks on this device — pick a theme anytime.";
  let margin = ' style="margin-top:0;padding-top:0;border-top:0"';
  let title = "Themes";
  if (grandparent) title = "How it looks";
  if (setup) {
    wrapCls = "sheet control-card setup-card setup-theme";
    headTag = "p";
    headCls = "setup-theme-head";
    lede = grandparent
      ? "This phone only. Choose a look that’s easy to read."
      : "This phone only. Scroll the grid for more looks.";
    margin = "";
  }
  if (grandparent && !setup) {
    wrapCls = "sheet control-card is-open gp-settings-card gp-theme-card";
    headTag = "h2";
    headCls = "gp-card-title";
    lede = "Pick a look that’s easy to read on this phone. High Contrast (light or dark) is best if text is hard to see.";
    margin = "";
  }
  const n = themes.length;
  const headLabel = grandparent ? title : withBetaBadge(title);
  const head =
    setup
      ? `<div class="setup-theme-head-row">
          <${headTag} class="${headCls}${grandparent ? "" : " parent-subhead-with-badge"}">${headLabel}</${headTag}>
          <p class="setup-theme-count">${n} ${n === 1 ? "look" : grandparent ? "looks" : "themes"}</p>
        </div>`
      : grandparent
        ? `<${headTag} class="${headCls}">${headLabel}</${headTag}>`
        : `<${headTag} class="${headCls} parent-subhead-with-badge">${headLabel}</${headTag}>`;
  return `
    <div class="${wrapCls}"${margin}>
      ${head}
      <p class="tiny">${lede}</p>
      ${grid}
    </div>`;
}

/** Short path preview on splash — not the full parent checklist. */
function splashPathPreviewHtml() {
  const steps =
    shouldConnectMothershipAfterTutorial() || state.pendingMothershipConnect
      ? ["Why PhoneHome", "Connect or host", "Sign in"]
      : prefersGrandparentTutorial()
        ? ["How it works", "Sign in", "Finish family setup"]
        : ["Why PhoneHome", "Sign in", "Finish family setup"];
  return `<ol class="splash-path" aria-label="What happens next">
    ${steps
      .map(
        (label, i) =>
          `<li${i === 0 ? ` class="is-now" aria-current="step"` : ""}><span class="splash-path-n">${i + 1}</span>${label}</li>`
      )
      .join("")}
  </ol>`;
}

function bindUiThemeSelector(scope = document, opts = {}) {
  const { onPick } = opts;
  scope.querySelectorAll("[data-ui-theme]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const theme = btn.getAttribute("data-ui-theme");
      setUiTheme(theme);
      scope.querySelectorAll("[data-ui-theme]").forEach((b) => {
        const on = b.getAttribute("data-ui-theme") === theme;
        b.classList.toggle("on", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      const chip = document.getElementById("parent-themes-chip");
      if (chip) {
        const strong = chip.querySelector("strong");
        if (strong) strong.textContent = uiThemeLabel(theme);
        else chip.textContent = uiThemeLabel(theme);
      }
      if (typeof onPick === "function") onPick(theme);
    });
  });
}

/** Accessibility controls shared by Parent → Accessibility and grandparent Settings. */
function a11ySettingsControlsHtml(opts = {}) {
  const { grandparent = false } = opts;
  const prefs = getA11yPrefs();
  const theme = getUiTheme();
  const hcOn = theme === "highContrast" || theme === "highContrastDark";
  const textOpts = [
    { id: "default", label: "Default" },
    { id: "large", label: "Large" },
    { id: "xlarge", label: grandparent ? "Extra large" : "Extra-large" },
  ];
  const motionOpts = [
    { id: "system", label: grandparent ? "Match phone" : "Match system" },
    { id: "reduce", label: grandparent ? "Less motion" : "Reduce motion" },
    { id: "full", label: grandparent ? "Keep motion" : "Allow motion" },
  ];
  const seg = (name, options, current) =>
    `<div class="a11y-seg" role="group" aria-label="${name}">
      ${options
        .map(
          (o) =>
            `<button type="button" class="a11y-seg-btn ${current === o.id ? "on" : ""}" data-a11y-${
              name === "Text size" ? "text" : "motion"
            }="${o.id}" aria-pressed="${current === o.id}">${o.label}</button>`
        )
        .join("")}
    </div>`;
  return `
    <div class="a11y-controls">
      <div class="parent-field a11y-field" style="margin-top:0;padding-top:0;border-top:0">
        <h3 class="parent-subhead">${grandparent ? "Text size" : "Text size"}</h3>
        <p class="tiny">${
          grandparent
            ? "Makes names and buttons easier to read on this phone."
            : "Scales the whole app on this device. Pinch-zoom also works."
        }</p>
        ${seg("Text size", textOpts, prefs.text)}
      </div>
      <div class="parent-field a11y-field">
        <h3 class="parent-subhead">${grandparent ? "Motion" : "Motion"}</h3>
        <p class="tiny">${
          grandparent
            ? "Turn down animations if they make the screen hard to follow."
            : "Honors your OS “Reduce motion” setting unless you override it here."
        }</p>
        ${seg("Motion", motionOpts, prefs.motion)}
      </div>
      <div class="parent-field a11y-field">
        <h3 class="parent-subhead">${grandparent ? "Easier to use" : "Extra help"}</h3>
        <label class="check-row">
          <input type="checkbox" id="a11y-targets" ${prefs.targets ? "checked" : ""} />
          Larger tap targets
        </label>
        <label class="check-row">
          <input type="checkbox" id="a11y-links" ${prefs.links ? "checked" : ""} />
          Always underline links
        </label>
        <label class="check-row">
          <input type="checkbox" id="a11y-focus" ${prefs.focus ? "checked" : ""} />
          Stronger keyboard focus ring
        </label>
      </div>
      <div class="parent-field a11y-field">
        <h3 class="parent-subhead">High contrast</h3>
        <p class="tiny">${
          grandparent
            ? "Black-on-white or white-on-black for the clearest text."
            : "WCAG-oriented themes with solid edges. Same options as Themes."
        }</p>
        <div class="btn-row two a11y-hc-row">
          <button type="button" class="ghost ${theme === "highContrast" ? "on" : ""}" id="a11y-hc-light" aria-pressed="${
            theme === "highContrast"
          }">Light high contrast</button>
          <button type="button" class="ghost ${theme === "highContrastDark" ? "on" : ""}" id="a11y-hc-dark" aria-pressed="${
            theme === "highContrastDark"
          }">Dark high contrast</button>
        </div>
        ${
          hcOn
            ? `<button type="button" class="linkish auth-link" id="a11y-hc-off" style="margin-top:8px">Back to ${
                grandparent ? "Modern" : "previous look (Modern)"
              }</button>`
            : ""
        }
      </div>
    </div>`;
}

function refreshA11ySummaryChip() {
  const chip = document.getElementById("parent-a11y-chip");
  if (!chip) return;
  const strong = chip.querySelector("strong");
  const label = a11ySummaryLabel();
  if (strong) strong.textContent = label;
  else chip.textContent = label;
}

function bindA11ySettings(scope = document) {
  const root = scope.querySelector(".a11y-controls") || scope;
  root.querySelectorAll("[data-a11y-text]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const text = btn.getAttribute("data-a11y-text");
      setA11yPrefs({ text });
      root.querySelectorAll("[data-a11y-text]").forEach((b) => {
        const on = b.getAttribute("data-a11y-text") === text;
        b.classList.toggle("on", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      refreshA11ySummaryChip();
      setFlash(text === "default" ? "Text size: default" : `Text size: ${text}`, "ok");
    });
  });
  root.querySelectorAll("[data-a11y-motion]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const motion = btn.getAttribute("data-a11y-motion");
      setA11yPrefs({ motion });
      root.querySelectorAll("[data-a11y-motion]").forEach((b) => {
        const on = b.getAttribute("data-a11y-motion") === motion;
        b.classList.toggle("on", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      refreshA11ySummaryChip();
      setFlash(
        motion === "reduce"
          ? "Motion reduced"
          : motion === "full"
            ? "Motion allowed"
            : "Motion follows your phone",
        "ok"
      );
    });
  });
  const wireCheck = (id, key, onMsg, offMsg) => {
    const el = root.querySelector(`#${id}`) || document.getElementById(id);
    if (!el) return;
    el.addEventListener("change", () => {
      setA11yPrefs({ [key]: Boolean(el.checked) });
      refreshA11ySummaryChip();
      setFlash(el.checked ? onMsg : offMsg, "ok");
    });
  };
  wireCheck("a11y-targets", "targets", "Larger tap targets on", "Larger tap targets off");
  wireCheck("a11y-links", "links", "Links underlined", "Link underlines off");
  wireCheck("a11y-focus", "focus", "Stronger focus ring on", "Focus ring default");
  const applyHc = (themeId) => {
    setUiTheme(themeId);
    refreshA11ySummaryChip();
    setFlash(themeId === "highContrastDark" ? "High Contrast Dark on" : "High Contrast on", "ok");
    // Re-render so theme picker + HC buttons stay in sync.
    render();
  };
  root.querySelector("#a11y-hc-light")?.addEventListener("click", () => applyHc("highContrast"));
  root.querySelector("#a11y-hc-dark")?.addEventListener("click", () => applyHc("highContrastDark"));
  root.querySelector("#a11y-hc-off")?.addEventListener("click", () => {
    setUiTheme("modern");
    setFlash("Back to Modern", "ok");
    render();
  });
}

/**
 * Subtle DeviceOrientation → CSS vars for atmosphere + presence-ring specular.
 * Heavily damped; iOS permission on first tap; off for reduced-motion / hidden tab.
 */
const specularTilt = {
  armed: false,
  listening: false,
  denied: false,
  enabling: false,
  raf: 0,
  /** @type {{ x: number, y: number }} */
  target: { x: 0, y: 0 },
  /** @type {{ x: number, y: number }} */
  current: { x: 0, y: 0 },
};

function prefersReducedMotion() {
  const motion = getA11yPrefs().motion;
  if (motion === "reduce") return true;
  if (motion === "full") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Focus trap + Escape for modal sheets (role=dialog). */
function bindModalA11y(wrap, { onClose } = {}) {
  if (!wrap) return () => {};
  const card = wrap.querySelector('[role="dialog"]') || wrap;
  const focusableSelector =
    'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
  const focusables = () =>
    [...card.querySelectorAll(focusableSelector)].filter(
      (el) => el.offsetParent !== null || el === document.activeElement
    );
  const prev = document.activeElement;
  queueMicrotask(() => {
    const list = focusables();
    (list[0] || card).focus?.();
  });
  const onKey = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      if (typeof onClose === "function") onClose();
      return;
    }
    if (e.key !== "Tab") return;
    const list = focusables();
    if (list.length < 2) {
      if (list.length === 1) e.preventDefault();
      return;
    }
    const i = list.indexOf(document.activeElement);
    if (e.shiftKey && (i <= 0)) {
      e.preventDefault();
      list[list.length - 1].focus();
    } else if (!e.shiftKey && (i === list.length - 1 || i < 0)) {
      e.preventDefault();
      list[0].focus();
    }
  };
  wrap.addEventListener("keydown", onKey);
  if (!card.hasAttribute("tabindex")) card.setAttribute("tabindex", "-1");
  return () => {
    wrap.removeEventListener("keydown", onKey);
    if (prev && typeof prev.focus === "function") {
      try {
        prev.focus();
      } catch {
        /* element may be gone after re-render */
      }
    }
  };
}

function clampTilt(n, min, max) {
  return Math.min(max, Math.max(min, n));
}

function applySpecularTiltVars(x, y) {
  const root = document.documentElement.style;
  // Atmosphere blobs drift a few %; rings rotate ~±14° with a soft glow offset.
  root.setProperty("--tilt-ax", `${(x * 5.5).toFixed(2)}%`);
  root.setProperty("--tilt-ay", `${(y * 4.2).toFixed(2)}%`);
  root.setProperty("--tilt-bx", `${(x * -4.5).toFixed(2)}%`);
  root.setProperty("--tilt-by", `${(y * 3.5).toFixed(2)}%`);
  root.setProperty("--tilt-cx", `${(x * 3.2).toFixed(2)}%`);
  root.setProperty("--tilt-cy", `${(y * -3.8).toFixed(2)}%`);
  root.setProperty("--tilt-ring", `${(x * -14 + y * 6).toFixed(2)}deg`);
  root.setProperty("--tilt-glow-x", `${(x * 2.8).toFixed(2)}px`);
  root.setProperty("--tilt-glow-y", `${(y * 2.4).toFixed(2)}px`);
}

function resetSpecularTiltVars() {
  specularTilt.target.x = 0;
  specularTilt.target.y = 0;
  specularTilt.current.x = 0;
  specularTilt.current.y = 0;
  applySpecularTiltVars(0, 0);
}

function onDeviceOrientationTilt(e) {
  if (document.hidden || prefersReducedMotion()) return;
  // Portrait phone: gamma = left/right, beta = front/back (rest ~45–70°).
  const x = clampTilt((e.gamma || 0) / 28, -1, 1);
  const y = clampTilt(((e.beta || 45) - 55) / 28, -1, 1);
  specularTilt.target.x = x;
  specularTilt.target.y = y;
}

function tickSpecularTilt() {
  const { current, target } = specularTilt;
  // Heavy damp — Apple-like lag, not 1:1 tracking.
  const lerp = document.hidden ? 0.18 : 0.075;
  current.x += (target.x - current.x) * lerp;
  current.y += (target.y - current.y) * lerp;
  if (document.hidden) {
    target.x *= 0.92;
    target.y *= 0.92;
  }
  applySpecularTiltVars(current.x, current.y);
  const settled =
    Math.abs(current.x) < 0.001 &&
    Math.abs(current.y) < 0.001 &&
    Math.abs(target.x) < 0.001 &&
    Math.abs(target.y) < 0.001;
  if (settled && document.hidden) {
    specularTilt.raf = 0;
    resetSpecularTiltVars();
    return;
  }
  specularTilt.raf = requestAnimationFrame(tickSpecularTilt);
}

function startSpecularTiltLoop() {
  if (specularTilt.raf) return;
  specularTilt.raf = requestAnimationFrame(tickSpecularTilt);
}

function attachDeviceOrientationTilt() {
  if (specularTilt.listening || specularTilt.denied || prefersReducedMotion()) return;
  window.addEventListener("deviceorientation", onDeviceOrientationTilt, { passive: true });
  specularTilt.listening = true;
  startSpecularTiltLoop();
}

async function enableSpecularTiltFromGesture() {
  if (specularTilt.listening || specularTilt.denied || specularTilt.enabling || prefersReducedMotion()) {
    return;
  }
  specularTilt.enabling = true;
  try {
    const DOE = /** @type {typeof DeviceOrientationEvent & { requestPermission?: () => Promise<PermissionState> }} */ (
      window.DeviceOrientationEvent
    );
    if (typeof DOE?.requestPermission === "function") {
      const perm = await DOE.requestPermission();
      if (perm !== "granted") {
        specularTilt.denied = true;
        return;
      }
    }
  } catch {
    specularTilt.denied = true;
    return;
  } finally {
    specularTilt.enabling = false;
  }
  attachDeviceOrientationTilt();
}

function armSpecularTilt() {
  if (specularTilt.armed || prefersReducedMotion()) return;
  if (typeof window.DeviceOrientationEvent === "undefined") return;
  specularTilt.armed = true;

  const DOE = /** @type {typeof DeviceOrientationEvent & { requestPermission?: () => Promise<PermissionState> }} */ (
    window.DeviceOrientationEvent
  );
  // Non-iOS: listen immediately. iOS: wait for a tap (permission requires gesture).
  if (typeof DOE.requestPermission !== "function") {
    attachDeviceOrientationTilt();
    return;
  }

  const onGesture = () => {
    document.removeEventListener("pointerdown", onGesture, true);
    document.removeEventListener("touchend", onGesture, true);
    void enableSpecularTiltFromGesture();
  };
  document.addEventListener("pointerdown", onGesture, { capture: true, once: true });
  document.addEventListener("touchend", onGesture, { capture: true, once: true });
}

function initSpecularTilt() {
  if (prefersReducedMotion()) return;
  armSpecularTilt();
  window.matchMedia("(prefers-reduced-motion: reduce)").addEventListener("change", (ev) => {
    if (ev.matches) {
      if (specularTilt.listening) {
        window.removeEventListener("deviceorientation", onDeviceOrientationTilt);
        specularTilt.listening = false;
      }
      if (specularTilt.raf) {
        cancelAnimationFrame(specularTilt.raf);
        specularTilt.raf = 0;
      }
      resetSpecularTiltVars();
    } else {
      specularTilt.armed = false;
      armSpecularTilt();
    }
  });
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      specularTilt.target.x = 0;
      specularTilt.target.y = 0;
      startSpecularTiltLoop();
    } else if (specularTilt.listening) {
      startSpecularTiltLoop();
    }
  });
}

/** @returns {"ios" | "android" | "desktop"} */
function installPlatform() {
  const ua = navigator.userAgent || "";
  const iOS =
    /iPad|iPhone|iPod/.test(ua) ||
    (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  if (iOS) return "ios";
  if (/Android/i.test(ua)) return "android";
  return "desktop";
}

function installSlide() {
  const platform = installPlatform();
  const canQuickInstall = Boolean(deferredInstallPrompt);
  if (platform === "ios") {
    return {
      id: "install",
      kicker: "iPhone app",
      title: "Best on iPhone: the free app",
      body: "Calls ring on your lock screen like a real phone, and Face ID signs you in.",
      platform,
      canQuickInstall: false,
    };
  }
  if (platform === "android") {
    return {
      id: "install",
      kicker: "Home screen",
      title: "Add it like an app",
      body: canQuickInstall
        ? "Tap Install to put PhoneHome on your home screen. Then open it from there."
        : "In Chrome, tap ⋮ → Install app (or Add to Home screen / Create shortcut). Then open PhoneHome from that icon.",
      platform,
      canQuickInstall,
    };
  }
  return {
    id: "install",
    kicker: "Home screen",
    title: "Add it like an app",
    body: "On iPhone: Safari → Share → Add to Home Screen. On Android: Chrome ⋮ → Install app or Add to Home screen. Works best on a phone.",
    platform,
    canQuickInstall,
  };
}

/**
 * True when this session should get the short grandparent How it works
 * (signed-in GP chrome, pending Grandma setup link, or ?grandparent= invite).
 */
function prefersGrandparentTutorial() {
  if (isGrandparentExperience()) return true;
  if (loadPendingGrandparentSetupToken()) return true;
  if (pendingInviteKind() === "grandparent") return true;
  return false;
}

function getTutorialSlides() {
  if (shouldConnectMothershipAfterTutorial() && !state.tutorialFromSettings) {
    if (prefersGrandparentTutorial()) {
      return GP_NATIVE_CONNECT_INTRO_SLIDES.map((s) => ({ ...s }));
    }
    return NATIVE_CONNECT_INTRO_SLIDES.map((s) => ({ ...s }));
  }
  if (prefersGrandparentTutorial()) {
    const gpSlides = GP_TUTORIAL_SLIDES.map((s) => ({ ...s }));
    if (isInstalledPhoneHome()) return gpSlides;
    gpSlides.push(installSlide());
    return gpSlides;
  }
  const slides = state.tutorialFromSettings
    ? TUTORIAL_SLIDES.map((s) => ({ ...s }))
    : introTourSlides();
  if (isInstalledPhoneHome()) return slides;
  slides.push(installSlide());
  return slides;
}

/** TreeHouse mark for tutorial scene (same mask glyph as pad 0). */
function tutorialTreeHouseHouseHtml() {
  return `<span class="scene-fr-house" aria-hidden="true"></span>`;
}

