function splashStoryHtml() {
  return `<figure class="splash-story">
    <div class="splash-story-hero">
      <img src="/assets/analog/kid-landline.jpg" width="1400" height="933" alt="A young kid talking on a house landline phone" />
    </div>
  </figure>`;
}

function tutorialBrandSlide() {
  return TUTORIAL_SLIDES.find((s) => s.id === "brand") || TUTORIAL_SLIDES[0];
}

/** Kicker / title / body — same type as How it works slides. */
function tutorialSlideCopyHtml(slide, { kicker: showKicker = true } = {}) {
  const kicker = showKicker
    ? slide.beta
      ? `<p class="tutorial-kicker">${slide.kicker} ${betaBadgeHtml()}</p>`
      : `<p class="tutorial-kicker">${slide.kicker}</p>`
    : "";
  let title = slide.title;
  let body = slide.bodyNoPricing && !purchaseLinksAllowed() ? slide.bodyNoPricing : slide.body;
  if (slide.id === "circles") {
    title = `${mothershipGlyphHtml("inline")}${slide.title}`;
    body = String(slide.body || "").replace(
      /<strong>Mothership<\/strong>/g,
      () => mothershipTermHtml()
    );
  }
  return `
    ${kicker}
    <h2 class="tutorial-title">${title}</h2>
    <p class="tutorial-lead">${body}</p>
    ${slide.houseMore ? tutorialHousePhoneMoreHtml() : ""}`;
}

