function browserTimeZone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch {
    return "UTC";
  }
}

/** Adult phone being edited — parent softphone or Open-their-phone GP line. */
function adultQuietLineId(hh = state.households[0]) {
  const active = state.activeLineId || "";
  if (active && (hh?.lines || []).some((l) => l.id === active && (l.mode || "parent") !== "child")) {
    return active;
  }
  const mine = (hh?.lines || []).find(
    (l) => l.owner_user_id === state.user?.id && (l.mode || "parent") !== "child"
  );
  return mine?.id || active || "";
}

/** Fields for PATCH …/rules when saving this adult’s DND / timezone. */
function adultQuietPatch(extra = {}, hh = state.households[0]) {
  const adult_line_id = adultQuietLineId(hh);
  return adult_line_id ? { ...extra, adult_line_id } : { ...extra };
}

function formatQuietClock(hhmm) {
  if (!hhmm) return "";
  const [h, m] = String(hhmm).split(":").map(Number);
  if (!Number.isFinite(h)) return "";
  const hour12 = h % 12 || 12;
  const ampm = h < 12 ? "am" : "pm";
  const mins = Number.isFinite(m) ? m : 0;
  // Omit :00 — "9pm" not "9:00pm"; keep non-zero minutes ("9:30pm").
  if (!mins) return `${hour12}${ampm}`;
  return `${hour12}:${String(mins).padStart(2, "0")}${ampm}`;
}

/** Display name for the configured schedule window (preset label or generic Quiet Time). */
function quietWindowName(hh) {
  const preset = String(hh?.schedule_preset || "");
  if (preset === "bedtime") return "Bedtime";
  if (preset === "school") return "School";
  return "Quiet Time";
}

function localMinutesInTz(date, timeZone) {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    }).formatToParts(date);
    const hour = Number(parts.find((p) => p.type === "hour")?.value ?? "0");
    const minute = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
    return hour * 60 + minute;
  } catch {
    return date.getHours() * 60 + date.getMinutes();
  }
}

function localIsoWeekdayInTz(date, timeZone) {
  try {
    const dayKey = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(date);
    const [y, m, d] = dayKey.split("-").map(Number);
    const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
    return dow === 0 ? 7 : dow;
  } catch {
    const dow = date.getDay();
    return dow === 0 ? 7 : dow;
  }
}

function parseQuietDaysClient(raw) {
  if (raw == null || String(raw).trim() === "") return null;
  const days = new Set();
  for (const part of String(raw).split(",")) {
    const n = Number(part.trim());
    if (Number.isInteger(n) && n >= 1 && n <= 7) days.add(n);
  }
  return days.size ? days : null;
}

/** Client mirror of server isQuietHoursActive (time + weekdays; holiday skip omitted). */
function isQuietHoursActiveClient(hh, date = new Date()) {
  if (!hh?.quiet_start || !hh?.quiet_end || !hh?.quiet_tz) return false;
  const [sh, sm] = String(hh.quiet_start).split(":").map(Number);
  const [eh, em] = String(hh.quiet_end).split(":").map(Number);
  if (![sh, sm, eh, em].every(Number.isFinite)) return false;
  const startM = sh * 60 + sm;
  const endM = eh * 60 + em;
  if (startM === endM) return false;
  const mins = localMinutesInTz(date, hh.quiet_tz);
  const inWindow = startM < endM ? mins >= startM && mins < endM : mins >= startM || mins < endM;
  if (!inWindow) return false;
  const days = parseQuietDaysClient(hh.quiet_days);
  if (days) {
    const wd = localIsoWeekdayInTz(date, hh.quiet_tz);
    if (!days.has(wd)) return false;
  }
  return true;
}

function quietSummary(hh) {
  if (!hh?.quiet_start || !hh?.quiet_end) return "Open — they can call anytime";
  const name = quietWindowName(hh);
  const tz = (hh.quiet_tz || "").split("/").pop()?.replace(/_/g, " ") || "local";
  const preset = hh.schedule_preset || "";
  const days =
    preset === "school" || (hh.quiet_days && String(hh.quiet_days).includes("1,2,3,4,5"))
      ? "Mon–Fri · "
      : "";
  const hol = hh.skip_holidays ? " · skip holidays" : "";
  return `${name} · ${days}${formatQuietClock(hh.quiet_start)}–${formatQuietClock(hh.quiet_end)} · ${tz}${hol}`;
}

function parentWindowName(hh) {
  const preset = String(hh?.parent_schedule_preset || "");
  if (preset === "evenings") return "Evenings";
  if (hh?.parent_quiet_start && hh?.parent_quiet_end) return "Do Not Disturb";
  return "Ring anytime";
}

function parentQuietSummary(hh) {
  if (!hh?.parent_quiet_start || !hh?.parent_quiet_end) return "Rings anytime";
  const tz = (hh.parent_quiet_tz || hh.quiet_tz || "").split("/").pop()?.replace(/_/g, " ") || "local";
  return `${parentWindowName(hh)} · ${formatQuietClock(hh.parent_quiet_start)}–${formatQuietClock(hh.parent_quiet_end)} · ${tz}`;
}

function isParentDndActiveClient(hh, date = new Date()) {
  return isQuietHoursActiveClient(
    {
      quiet_start: hh?.parent_quiet_start,
      quiet_end: hh?.parent_quiet_end,
      quiet_tz: hh?.parent_quiet_tz || hh?.quiet_tz,
      quiet_days: hh?.parent_quiet_days,
      skip_holidays: 0,
      schedule_preset: hh?.parent_schedule_preset || "evenings",
    },
    date
  );
}

function kidHoursStatusLine(hh) {
  if (hh?.dnd) return "Quiet Time is on now — VIP still rings";
  if (isQuietHoursActiveClient(hh)) return `${quietWindowName(hh)} is on now`;
  return quietSummary(hh);
}

function parentHoursChipHtml(hh, kidLines) {
  const kid = kidLines[0];
  const kidBit = kid
    ? `${(kid.child_label || kid.name || "Kids").replace(/</g, "&lt;")} · ${
        hh?.schedule_preset === "bedtime"
          ? "Bedtime"
          : hh?.schedule_preset === "school"
            ? "School"
            : hh?.quiet_start
              ? "Custom"
              : "Open"
      }`
    : "No kid yet";
  const youBit = !hh?.parent_quiet_start ? "You · rings" : `You · ${parentWindowName(hh)}`;
  return `<span class="parent-summary-chip" id="parent-hours-chip"><strong>${kidBit}</strong><span>${youBit}</span></span>`;
}

function schedUsageHtml(used, cap) {
  if (cap == null) {
    return `<p class="tiny sched-talk">Talk today <strong>${used} min</strong> · no daily limit</p>`;
  }
  const pct = Math.min(100, Math.round((used / Math.max(cap, 1)) * 100));
  return `<div class="usage-bar ${pct >= 90 ? "hot" : ""}">
    <div class="usage-meta"><span>Talk today</span><strong>${used} / ${cap} min</strong></div>
    <div class="usage-track"><i style="width:${pct}%"></i></div>
  </div>`;
}

function renderParentHoursBody(hh, kidLines) {
  const preset = hh?.schedule_preset || "bedtime";
  const cap = hh?.daily_cap_minutes;
  const parentPreset = hh?.parent_schedule_preset || "evenings";
  const showKidsCustom = Boolean(state.parentHoursKidsCustom) || preset === "custom";
  const showYouCustom = Boolean(state.parentHoursYouCustom) || parentPreset === "custom";
  const kidNames = kidLines.map((l) => l.child_label || l.name || "this kid");
  const kidList =
    kidNames.length === 0
      ? ""
      : kidNames.length === 1
        ? kidNames[0]
        : kidNames.length === 2
          ? `${kidNames[0]} and ${kidNames[1]}`
          : `${kidNames.slice(0, -1).join(", ")}, and ${kidNames[kidNames.length - 1]}`;
  const kidCards = kidLines.length
    ? kidLines
        .map((l) => {
          const name = (l.child_label || l.name || "Kid").replace(/</g, "&lt;");
          const used = l.usage_today_minutes || 0;
          return `<article class="sched-person">
            <div class="sched-person-head">
              ${avatarHtml(l.child_label || l.name, l.id, "md")}
              <div class="sched-person-copy">
                <strong>${name}</strong>
                <p class="tiny">${kidHoursStatusLine(hh).replace(/</g, "&lt;")}</p>
              </div>
            </div>
            ${schedUsageHtml(used, cap)}
          </article>`;
        })
        .join("")
    : `<p class="tiny sched-empty">Add a kid in <button type="button" class="linkish" id="hours-go-line">Kids</button>, then set their hours here.</p>`;

  const parentTz = hh?.parent_quiet_tz || browserTimeZone();
  const kidsTz = parentTz;
  const kidsTzLabel = (kidsTz || "").split("/").pop()?.replace(/_/g, " ") || kidsTz;
  return `
        <div class="sched-block">
          <h3 class="parent-subhead">Kids</h3>
          <p class="tiny">${
            kidLines.length
              ? `Hours and a daily talk limit for <strong>${kidList.replace(/</g, "&lt;")}</strong>. VIP contacts still ring.`
              : "These limits apply to each kid line you manage."
          }</p>
          ${kidCards}
          ${
            kidLines.length
              ? `<div class="parent-field sched-editor">
          <h3 class="parent-subhead">Their hours</h3>
          <div class="preset-grid">
            ${["open", "bedtime", "school"]
              .map(
                (p) =>
                  `<button type="button" class="preset ${preset === p ? "on" : ""}" data-preset="${p}">${
                    p === "open" ? "Open" : p === "bedtime" ? "Bedtime" : "School"
                  }</button>`
              )
              .join("")}
          </div>
          <button class="ghost" id="custom-quiet" type="button">Custom hours…</button>
          <p class="tiny parent-inline-meta">${quietSummary(hh)} · ${kidsTzLabel.replace(/</g, "&lt;")} <span class="tiny">(same as your phone)</span></p>
          ${
            showKidsCustom
              ? `<div class="sched-custom" id="kids-custom-fields">
            <label>Starts</label>
            <input type="time" id="kids-q-start" value="${hh?.quiet_start || "20:00"}" />
            <label>Ends</label>
            <input type="time" id="kids-q-end" value="${hh?.quiet_end || "07:00"}" />
            <p class="tiny">Timezone matches your phone (${kidsTz.replace(/</g, "")}).</p>
            <button class="primary" type="button" id="save-kids-custom">Save custom hours</button>
          </div>`
              : ""
          }
          ${
            preset === "school"
              ? `<div class="school-schedule-note">
            <p class="tiny"><strong>School</strong> is Mon–Fri ${formatQuietClock(hh.quiet_start || "08:00")}–${formatQuietClock(hh.quiet_end || "15:30")}.</p>
            <label class="check-row">
              <input type="checkbox" id="skip-holidays" ${hh.skip_holidays ? "checked" : ""} />
              <span>Skip US federal holidays</span>
            </label>
            <p class="tiny">Observed New Year’s, MLK, Presidents’, Memorial, Juneteenth, July 4, Labor, Columbus/Indigenous Peoples’, Veterans, Thanksgiving, Christmas. Not a full school calendar.</p>
          </div>`
              : ""
          }
        </div>
        <div class="parent-field">
          <h3 class="parent-subhead">Daily talk limit</h3>
          <p class="tiny">Each kid gets this many minutes. Blank = unlimited.</p>
          <label>Minutes per day</label>
          <input id="cap" type="number" min="0" step="5" placeholder="e.g. 60" value="${cap ?? ""}" />
          <button class="primary" id="save-cap" type="button">Save limit</button>
        </div>`
              : ""
          }
        </div>
        <div class="sched-block sched-block-you">
          <h3 class="parent-subhead">Your phone</h3>
          <p class="tiny">${
            isParentDndActiveClient(hh)
              ? "Do Not Disturb is on now — VIP still rings."
              : "Your own Do Not Disturb. Kids use your timezone for bedtime and school."
          }</p>
          <p class="sched-you-status">${parentQuietSummary(hh).replace(/</g, "&lt;")}</p>
          <div class="preset-grid sched-you-presets">
            ${["open", "evenings", "custom"]
              .map((p) => {
                const label = p === "open" ? "Ring anytime" : p === "evenings" ? "Evenings" : "Custom";
                const on = parentPreset === p || (p === "custom" && showYouCustom && parentPreset === "custom");
                return `<button type="button" class="preset ${on ? "on" : ""}" data-parent-preset="${p}">${label}</button>`;
              })
              .join("")}
          </div>
          ${
            showYouCustom
              ? `<div class="sched-custom" id="you-custom-fields">
            <label>Starts</label>
            <input type="time" id="you-q-start" value="${hh?.parent_quiet_start || "21:00"}" />
            <label>Ends</label>
            <input type="time" id="you-q-end" value="${hh?.parent_quiet_end || "07:00"}" />
            <label>Timezone</label>
            <select id="you-q-tz">${timezoneOptions(parentTz)}</select>
            <button class="primary" type="button" id="save-you-custom">Save my hours</button>
          </div>`
              : `<p class="tiny parent-inline-meta">Evenings are 9pm–7am. VIP contacts still ring your phone.</p>`
          }
        </div>`;
}

function timezoneOptions(selected) {
  const detected = browserTimeZone();
  const zones = [
    detected,
    "America/New_York",
    "America/Chicago",
    "America/Denver",
    "America/Los_Angeles",
    "America/Phoenix",
    "America/Anchorage",
    "Pacific/Honolulu",
    "UTC",
  ];
  const unique = [...new Set(zones.filter(Boolean))];
  if (selected && !unique.includes(selected)) unique.unshift(selected);
  return unique
    .map((z) => `<option value="${z}" ${z === selected ? "selected" : ""}>${z === detected ? `${z} (this device)` : z}</option>`)
    .join("");
}

function msEsc(s) {
  return String(s ?? "").replace(/</g, "&lt;").replace(/"/g, "&quot;");
}

function msLineLabel(line) {
  if (line.mode === "child") return line.child_label || line.name || "Kid";
  if (line.mode === "grandparent") return line.name || "Grandparent";
  return line.name || "Parent line";
}

function msPresenceChip(line) {
  const bits = [];
  if (line.softphone_online) bits.push(`<span class="billing-chip billing-online">App online</span>`);
  else bits.push(`<span class="billing-chip">App off</span>`);
  if (line.ios_push) bits.push(`<span class="billing-chip">iOS push</span>`);
  if (line.has_ata) {
    const st = line.ata?.sip?.status || "unknown";
    const label =
      st === "online"
        ? "ATA Working"
        : st === "waiting"
          ? "ATA waiting"
          : st === "offline"
            ? "ATA offline"
            : st === "not_configured"
              ? "ATA not set up"
              : "ATA ?";
    bits.push(`<span class="billing-chip billing-ata-${st}">${label}</span>`);
  }
  return bits.join(" ");
}

function renderMothershipBillingCircleRows(pods) {
  const withCircles = (pods || []).filter((p) => (p.circles || []).length);
  if (!withCircles.length) return `<p class="tiny">No kid Circles yet.</p>`;
  return withCircles
    .map((pod) => {
      const circles = pod.circles || [];
      const rows = circles
        .map((c) => {
          const eff = c.effective_status || c.status;
          const lineId = c.line_id;
          const actions = c.billing_configured
            ? `<button type="button" class="ghost tiny-btn" data-bill-action="paid" data-line-id="${lineId}">Paid</button>
              <button type="button" class="ghost tiny-btn" data-bill-action="grace" data-line-id="${lineId}">Grace</button>
              <button type="button" class="ghost tiny-btn" data-bill-action="suspend" data-line-id="${lineId}">Pause</button>
              <button type="button" class="ghost tiny-btn" data-bill-action="comp" data-line-id="${lineId}">Comp</button>`
            : `<span class="tiny">Save settings to apply</span>`;
          return `<tr data-line-id="${lineId}">
            <td>${msEsc(c.kid_name || "Kid")}</td>
            <td>${formatUsdCents(c.monthly_cents)}</td>
            <td><span class="billing-chip billing-${eff}">${circleBillingStatusLabel(eff)}</span></td>
            <td class="billing-actions">${actions}</td>
          </tr>`;
        })
        .join("");
      return `<div class="mothership-pod-block">
        <h3 class="parent-subhead">${msEsc(pod.name || "Pod")}</h3>
        <table class="billing-table">
          <thead><tr><th>Circle</th><th>Rate</th><th>Status</th><th></th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>`;
    })
    .join("");
}

function renderMothershipPodMap(pods) {
  if (!pods?.length) return `<p class="tiny">No Pods on this ${mothershipTermHtml({ strong: false })} yet.</p>`;
  return pods
    .map((pod) => {
      const parents = (pod.parents || [])
        .map((p) => {
          const uname = p.username ? `@${msEsc(p.username)}` : "no username";
          const op =
            p.operator_role === "owner"
              ? ` · <span class="billing-chip">owner</span>`
              : p.is_operator
                ? ` · <span class="billing-chip">operator</span>`
                : "";
          const reset =
            p.username
              ? `<button type="button" class="ghost tiny-btn" data-ms-reset-user="${msEsc(p.username)}" data-ms-reset-name="${msEsc(p.display_name)}">Reset password</button>`
              : "";
          return `<li class="ms-parent-row">
            <div>
              <strong>${msEsc(p.display_name)}</strong>
              <span class="tiny"> ${uname}${op}</span>
            </div>
            ${reset}
          </li>`;
        })
        .join("");
      const lines = (pod.lines || [])
        .map((line) => {
          const kind =
            line.mode === "child" ? "Kid" : line.mode === "grandparent" ? "GP" : "Line";
          const ataBit = line.has_ata
            ? ` · ATA ${msEsc(line.ata?.sip_extension || "?")} (${msEsc(line.ata?.sip_host_kind || "")})`
            : "";
          return `<li class="ms-line-row">
            <div>
              <strong>${msEsc(msLineLabel(line))}</strong>
              <span class="tiny"> · ${kind} · ${msEsc(line.type || "softphone")}${ataBit}</span>
              <div class="ms-presence">${msPresenceChip(line)}</div>
            </div>
          </li>`;
        })
        .join("");
      const timeout = pod.kill_switch
        ? `<span class="billing-chip billing-suspended">Timeout on</span>`
        : "";
      return `<details class="ms-pod-card" ${pod.kid_count ? "" : ""}>
        <summary>
          <strong>${msEsc(pod.name || "Pod")}</strong>
          <span class="tiny">${pod.parent_count} parent${pod.parent_count === 1 ? "" : "s"} · ${pod.kid_count} kid${pod.kid_count === 1 ? "" : "s"} · ${pod.line_count} line${pod.line_count === 1 ? "" : "s"}</span>
          ${timeout}
        </summary>
        <div class="ms-pod-body">
          <h4 class="parent-subhead">Parents</h4>
          <ul class="ms-list">${parents || `<li class="tiny">No parents</li>`}</ul>
          <h4 class="parent-subhead">Lines</h4>
          <ul class="ms-list">${lines || `<li class="tiny">No lines</li>`}</ul>
        </div>
      </details>`;
    })
    .join("");
}

function renderMothershipOperators(snap) {
  const ops = snap.operators || [];
  const amOwner = state.mothership?.operator_role === "owner";
  const rows = ops
    .map((o) => {
      const canRemove = amOwner && o.role !== "owner";
      return `<li class="ms-parent-row">
        <div>
          <strong>${msEsc(o.display_name)}</strong>
          <span class="tiny"> ${o.username ? `@${msEsc(o.username)}` : ""} · ${msEsc(o.role)}</span>
        </div>
        ${
          canRemove
            ? `<button type="button" class="ghost tiny-btn" data-ms-remove-op="${msEsc(o.user_id)}">Remove</button>`
            : ""
        }
      </li>`;
    })
    .join("");
  return `<section class="control-card mothership-ops-panel">
    <h3 class="parent-subhead">Operators</h3>
    <p class="tiny">People who can open this admin console. Only the <strong>owner</strong> can add or remove operators.</p>
    <ul class="ms-list">${rows}</ul>
    ${
      amOwner
        ? `<div class="ms-add-op">
      <label for="ms-op-username">Add operator by username</label>
      <div class="ms-inline-row">
        <input id="ms-op-username" type="text" autocomplete="username" placeholder="their username" />
        <button type="button" class="ghost" id="ms-add-op">Add</button>
      </div>
    </div>`
        : `<p class="tiny">Ask the Mothership owner to add you as an operator.</p>`
    }
  </section>`;
}

function renderMothershipSupportTools() {
  return `<section class="control-card mothership-support-panel">
    <h3 class="parent-subhead">Reset a parent password</h3>
    <p class="tiny">When someone forgets their login — generates a new password you tell them privately. Does not email them.</p>
    <label for="ms-reset-username">Username</label>
    <input id="ms-reset-username" type="text" autocomplete="username" placeholder="username" />
    <label for="ms-reset-password">New password</label>
    <input id="ms-reset-password" type="text" autocomplete="new-password" placeholder="at least 8 characters" />
    <button type="button" class="ghost" id="ms-reset-pass" style="margin-top:10px">Reset password</button>
  </section>`;
}

async function renderMothershipAdmin(opts = {}) {
  const refresh = Boolean(opts.refresh);
  let snap = refresh ? null : state.mothershipAdminSnapshot;
  try {
    snap = await loadMothershipAdmin(refresh);
  } catch (e) {
    app.innerHTML = `
      <div class="topbar">
        <button class="icon-btn" id="ms-back">←</button>
        ${mothershipMarkHtml()}
        <span style="width:40px"></span>
      </div>
      <div class="sheet"><p class="error">${msEsc(e.message || "Could not load Mothership admin")}</p></div>`;
    document.getElementById("ms-back")?.addEventListener("click", () => {
      state.screen = "home";
      state.nav = "controls";
      render();
    });
    return;
  }

  const cap = snap.capacity || state.mothership || {};
  const settings = snap.settings || {};
  const enabled = Boolean(settings.enabled);
  const defaultDollars =
    settings.default_monthly_cents != null ? (settings.default_monthly_cents / 100).toFixed(2) : "";
  const summary = snap.summary || {};
  const server = snap.server || {};
  const health = snap.health || {};
  const integrity = snap.integrity || {};
  const integrityWarn =
    (integrity.orphan_guardians || 0) +
      (integrity.orphan_allowlist_targets || 0) +
      (integrity.duplicate_speed_dials || 0) >
    0;

  app.innerHTML = `
    <div class="topbar">
      <button class="icon-btn" id="ms-back">←</button>
      ${mothershipMarkHtml()}
      <button type="button" class="ghost tiny-btn" id="ms-refresh" title="Refresh health">↻</button>
    </div>
    <div class="sheet mothership-admin">
      <h2>Server overview</h2>
      <p class="tiny">You run this ${mothershipTermHtml({ strong: false })} — Pods, lines, health, and optional sibling billing.</p>

      <div class="parent-pill-row" aria-live="polite">
        <span class="parent-pill is-on"><span class="dot"></span>${cap.podCount ?? "—"}${cap.maxPods != null ? `/${cap.maxPods}` : ""} Pods</span>
        <span class="parent-pill is-on"><span class="dot"></span>${cap.lineCount ?? "—"}/${cap.maxLines ?? "—"} lines</span>
        <span class="parent-pill is-on"><span class="dot"></span>${summary.kid_line_count ?? 0} kid Circles</span>
      </div>

      <section class="control-card mothership-server-panel">
        <h3 class="parent-subhead">Connection</h3>
        <p class="tiny">Invite, Grandma setup, and co-parent <strong>share links</strong> are built from the App URL below (<code>PUBLIC_BASE_URL</code>). If that URL is wrong, phones can’t redeem links.</p>
        <dl class="ms-kv">
          <div><dt>App URL</dt><dd class="ms-kv-url"><span id="ms-public-url">${msEsc(server.public_base_url || "not set")}</span>${
            server.public_base_url
              ? ` <button type="button" class="ghost tiny-btn" id="ms-copy-public-url">Copy</button>`
              : ""
          }</dd></div>
          <div><dt>SIP host</dt><dd>${msEsc(server.sip_public_host || "not set")}</dd></div>
          <div><dt>ATA one-tap (LAN)</dt><dd>${server.ata_lan_push ? "On" : "Off"}</dd></div>
          <div><dt>Bridge</dt><dd>${server.bridge_configured ? "Configured" : "Not configured"}</dd></div>
          <div><dt>FreePBX sync</dt><dd>${server.freepbx_sync_configured ? "Configured" : "Not configured"}</dd></div>
        </dl>
        <p class="tiny">Share tokens: <code>/?join=</code> (family / friend / co-parent), <code>/?gp=</code> (Grandma one-tap), <code>/?invite=</code> (6-digit code). iOS Connect accepts a full share link and keeps the token.</p>
      </section>

      <section class="control-card mothership-health-panel">
        <h3 class="parent-subhead">Health</h3>
        <div class="parent-pill-row">
          <span class="parent-pill is-on"><span class="dot"></span>Apps ${health.softphone_online ?? 0}/${health.softphone_total ?? 0}</span>
          <span class="parent-pill is-on"><span class="dot"></span> ATA ok ${health.ata_online ?? 0}/${health.ata_total ?? 0}</span>
          ${
            health.ata_offline
              ? `<span class="parent-pill is-quiet"><span class="dot"></span> ATA off ${health.ata_offline}</span>`
              : ""
          }
          ${
            health.ata_waiting
              ? `<span class="parent-pill is-quiet"><span class="dot"></span> ATA wait ${health.ata_waiting}</span>`
              : ""
          }
          ${
            health.ios_push_lines
              ? `<span class="parent-pill is-on"><span class="dot"></span> iOS push ${health.ios_push_lines}</span>`
              : ""
          }
        </div>
        ${
          integrityWarn
            ? `<p class="flash warn tiny" role="status">Integrity: ${integrity.orphan_guardians || 0} orphan guardians · ${integrity.orphan_allowlist_targets || 0} orphan contacts · ${integrity.duplicate_speed_dials || 0} duplicate dials</p>`
            : `<p class="tiny">No integrity warnings.</p>`
        }
        <button type="button" class="ghost tiny-btn" id="ms-refresh-health">Refresh ATA registration</button>
      </section>

      <section class="control-card mothership-pods-panel">
        <h3 class="parent-subhead">Pods on this ${mothershipTermHtml({ strong: false })}</h3>
        <p class="tiny">Every family on this server — parents, kid Circles, and line status.</p>
        <div class="ms-pod-map">${renderMothershipPodMap(snap.pods)}</div>
      </section>

      ${renderMothershipOperators(snap)}
      ${renderMothershipSupportTools()}

      ${purchaseLinksAllowed() ? `<section class="control-card mothership-billing-panel">
        <h3 class="parent-subhead">Circle billing (optional)</h3>
        <p class="tiny">Charge siblings per kid Circle and collect off-platform (Venmo, Zelle, etc.). PhoneHome never takes a cut.</p>
        <label class="check-row">
          <input type="checkbox" id="ms-billing-enabled" ${enabled ? "checked" : ""} />
          <span>Enable Circle billing on this Mothership</span>
        </label>

        <div id="ms-billing-fields" class="${enabled ? "" : "hidden"}">
          <label for="ms-default-rate">Default rate per Circle (USD / month)</label>
          <input type="number" id="ms-default-rate" min="0" step="0.01" placeholder="5.00" value="${defaultDollars}" />

          <label for="ms-payment-instructions">Payment instructions for siblings</label>
          <textarea id="ms-payment-instructions" rows="2" placeholder="${pricesShownInApp() ? "Venmo @you — $5 per kid, due the 1st" : "How families can reach you about hosting"}">${msEsc(settings.payment_instructions || "")}</textarea>

          <label for="ms-enforcement">When a Circle is paused</label>
          <select id="ms-enforcement">
            <option value="none" ${settings.enforcement === "none" ? "selected" : ""}>Track only — never block calls</option>
            <option value="warn" ${settings.enforcement === "warn" ? "selected" : ""}>Warn parents in the app</option>
            <option value="soft" ${settings.enforcement === "soft" ? "selected" : ""}>Soft — block cross-Pod calls for paused Circles</option>
            <option value="hard" ${settings.enforcement === "hard" ? "selected" : ""}>Hard — block all calls for paused Circles</option>
          </select>

          <label for="ms-grace-days">Grace period (days)</label>
          <input type="number" id="ms-grace-days" min="0" max="90" value="${settings.grace_days ?? 7}" />

          <button type="button" class="primary" id="ms-save-settings">Save billing settings</button>

          <div class="mothership-billing-summary tiny">
            <p>Suggested monthly total: <strong>${formatUsdCents(summary.suggested_monthly_total_cents)}</strong>
            · Active: ${summary.active_count ?? 0} · Comped: ${summary.comp_count ?? 0} · Overdue: ${summary.overdue_count ?? 0}</p>
          </div>

          ${renderMothershipBillingCircleRows(snap.pods)}
        </div>
      </section>` : ""}
    </div>
  `;

  const goBack = () => {
    state.screen = "home";
    state.nav = "controls";
    render();
  };
  document.getElementById("ms-back")?.addEventListener("click", goBack);
  document.getElementById("ms-refresh")?.addEventListener("click", () => {
    void renderMothershipAdmin({ refresh: false });
  });
  document.getElementById("ms-refresh-health")?.addEventListener("click", () => {
    setFlash("Checking ATA registration…", "ok");
    void renderMothershipAdmin({ refresh: true });
  });
  document.getElementById("ms-copy-public-url")?.addEventListener("click", async () => {
    const url = String(server.public_base_url || "").trim();
    if (!url) return;
    try {
      await navigator.clipboard.writeText(url);
      setFlash("App URL copied — paste it in a text or on Connect", "ok");
    } catch {
      setFlash("Couldn’t copy — select the URL manually", "warn");
    }
  });

  const fields = document.getElementById("ms-billing-fields");
  document.getElementById("ms-billing-enabled")?.addEventListener("change", (e) => {
    fields?.classList.toggle("hidden", !e.target.checked);
  });

  document.getElementById("ms-save-settings")?.addEventListener("click", async () => {
    try {
      const on = document.getElementById("ms-billing-enabled").checked;
      const rateRaw = document.getElementById("ms-default-rate").value;
      const rate = rateRaw === "" ? null : Math.round(Number.parseFloat(rateRaw) * 100);
      const body = {
        enabled: on,
        enforcement: document.getElementById("ms-enforcement").value,
        default_monthly_cents: rate,
        grace_days: Number(document.getElementById("ms-grace-days").value) || 7,
        payment_instructions: document.getElementById("ms-payment-instructions").value,
      };
      const data = await api("/api/mothership/billing/settings", {
        method: "PATCH",
        body: JSON.stringify(body),
      });
      state.mothership = { ...(state.mothership || {}), billing_enabled: data.settings?.enabled };
      setFlash(on ? "Circle billing enabled" : "Circle billing off", "ok");
      await refresh();
      state.screen = "mothership-admin";
      void renderMothershipAdmin();
    } catch (e) {
      setFlash(e.message || "Could not save", "error");
    }
  });

  document.querySelectorAll("[data-bill-action]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const lineId = btn.getAttribute("data-line-id");
      const action = btn.getAttribute("data-bill-action");
      const status =
        action === "paid"
          ? null
          : action === "grace"
            ? "grace"
            : action === "suspend"
              ? "suspended"
              : action === "comp"
                ? "comp"
                : null;
      try {
        if (action === "paid") {
          await api(`/api/mothership/billing/circles/${lineId}/mark-paid`, { method: "POST" });
        } else {
          await api(`/api/mothership/billing/circles/${lineId}`, {
            method: "PATCH",
            body: JSON.stringify({ status }),
          });
        }
        setFlash("Circle billing updated", "ok");
        state.screen = "mothership-admin";
        void renderMothershipAdmin();
      } catch (e) {
        setFlash(e.message || "Could not update", "error");
      }
    });
  });

  async function doResetPassword(username, password) {
    const user = String(username || "").trim();
    const pass = String(password || "").trim();
    if (!user || !pass) {
      setFlash("Username and new password required", "warn");
      return;
    }
    try {
      const data = await api("/api/mothership/users/reset-password", {
        method: "POST",
        body: JSON.stringify({ username: user, password: pass }),
      });
      setFlash(`Password reset for @${data.username}`, "ok");
      const u = document.getElementById("ms-reset-username");
      const p = document.getElementById("ms-reset-password");
      if (u) u.value = "";
      if (p) p.value = "";
    } catch (e) {
      setFlash(e.message || "Could not reset", "error");
    }
  }

  document.getElementById("ms-reset-pass")?.addEventListener("click", () => {
    void doResetPassword(
      document.getElementById("ms-reset-username")?.value,
      document.getElementById("ms-reset-password")?.value
    );
  });

  document.querySelectorAll("[data-ms-reset-user]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const username = btn.getAttribute("data-ms-reset-user");
      const name = btn.getAttribute("data-ms-reset-name") || username;
      const password = window.prompt(`New password for ${name} (@${username})`);
      if (password == null) return;
      void doResetPassword(username, password);
    });
  });

  document.getElementById("ms-add-op")?.addEventListener("click", async () => {
    const username = String(document.getElementById("ms-op-username")?.value || "").trim();
    if (!username) {
      setFlash("Enter a username", "warn");
      return;
    }
    try {
      await api("/api/mothership/operators", {
        method: "POST",
        body: JSON.stringify({ username }),
      });
      setFlash(`Added @${username} as operator`, "ok");
      void renderMothershipAdmin();
    } catch (e) {
      setFlash(e.message || "Could not add", "error");
    }
  });

  document.querySelectorAll("[data-ms-remove-op]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const userId = btn.getAttribute("data-ms-remove-op");
      if (!window.confirm("Remove this operator?")) return;
      try {
        await api(`/api/mothership/operators/${encodeURIComponent(userId)}`, { method: "DELETE" });
        setFlash("Operator removed", "ok");
        void renderMothershipAdmin();
      } catch (e) {
        setFlash(e.message || "Could not remove", "error");
      }
    });
  });
}

function renderQuietHours() {
  const hh = state.households[0];
  const enabled = Boolean(hh?.quiet_start && hh?.quiet_end);
  const start = hh?.quiet_start || "21:00";
  const end = hh?.quiet_end || "07:00";
  const tz = hh?.quiet_tz || browserTimeZone();

  app.innerHTML = `
    <div class="topbar">
      <button class="icon-btn" id="back">←</button>
      <div class="mark">Quiet Time</div>
      <span style="width:40px"></span>
    </div>
    <div class="sheet">
      <h2>Your family’s Quiet Time window</h2>
      <p>Calls are blocked during this window in <strong>your</strong> timezone — not the Mothership’s clock.</p>
      <label class="check-row">
        <input type="checkbox" id="q-on" ${enabled ? "checked" : ""} />
        <span>Enable Quiet Time</span>
      </label>
      <div id="q-fields" class="${enabled ? "" : "hidden"}">
        <label>Starts</label>
        <input type="time" id="q-start" value="${start}" />
        <label>Ends</label>
        <input type="time" id="q-end" value="${end}" />
        <label>Timezone</label>
        <select id="q-tz">${timezoneOptions(tz)}</select>
        <p class="tiny">Detected on this phone as ${browserTimeZone()}. Cousins should set their own window in their timezone.</p>
      </div>
      <p class="error hidden" id="q-err"></p>
      <button class="primary" id="q-save">Save</button>
    </div>
  `;

  const fields = document.getElementById("q-fields");
  document.getElementById("q-on").onchange = (e) => {
    fields.classList.toggle("hidden", !e.target.checked);
  };
  document.getElementById("back").onclick = () => {
    state.screen = "home";
    render();
  };
  document.getElementById("q-save").onclick = async () => {
    const err = document.getElementById("q-err");
    err.classList.add("hidden");
    try {
      const on = document.getElementById("q-on").checked;
      const body = on
        ? {
            quiet_start: document.getElementById("q-start").value,
            quiet_end: document.getElementById("q-end").value,
            quiet_tz: document.getElementById("q-tz").value,
          }
        : { quiet_start: null, quiet_end: null };
      await api(`/api/households/${hh.id}/rules`, {
        method: "PATCH",
        body: JSON.stringify(body),
      });
      setFlash(on ? "Quiet Time saved" : "Quiet Time off", "ok");
      state.screen = "home";
      await refresh();
    } catch (e) {
      err.textContent = e.message || "Could not save";
      err.classList.remove("hidden");
    }
  };
}

function inviteKindFromState() {
  return state.inviteKind === "friend"
    ? "friend"
    : state.inviteKind === "grandparent"
      ? "grandparent"
      : "family";
}

async function renderInvite() {
  if (!canInviteFamily()) {
    setFlash("Ask a parent to invite family", "warn");
    state.screen = "home";
    render();
    return;
  }
  const hh = state.households[0];
  if (!hh?.id) {
    setFlash("Add your family first, then invite", "warn");
    state.screen = "home";
    render();
    return;
  }
  // Grandma is create-login, not an invite code — never stay on this screen for that path.
  if (state.inviteKind === "grandparent") {
    state.inviteKind = "family";
    state.screen = "home";
    void openParentPanel({ scrollTo: "gp-setup-form" });
    return;
  }
  const kids = householdKidLines(hh);
  let inviteKind = inviteKindFromState();
  if (inviteKind === "grandparent") inviteKind = "family";
  let friendKidId = state.inviteFriendKidId || (kids[0] && kids[0].id) || "";
  let sharePayload = null;
  const kidOpts = kids
    .map((k) => {
      const id = String(k.id || "").replace(/"/g, "&quot;");
      const name = String(k.child_label || k.name || "Kid").replace(/</g, "");
      return `<option value="${id}" ${k.id === friendKidId ? "selected" : ""}>${name}</option>`;
    })
    .join("");
  setAppPage(`
    <div class="invite-flow-page">
    <div class="topbar invite-flow-topbar">
      <button type="button" class="icon-btn" id="back">←</button>
      <div class="mark">Invite</div>
      <span style="width:40px"></span>
    </div>
    <div class="invite-hero sheet">
      <p class="invite-eyebrow">Share a link</p>
      <h2>Invite family or a friend</h2>
      <p class="tiny">Always invite another <strong>parent</strong> — they add their own kids. A sister joins this Pod (shared grandparents). A friend’s parent joins one kid’s Circle. <button type="button" class="linkish" id="invite-go-grandma">Adding Grandma?</button> — you create their login instead.</p>
      <div class="invite-kind-cards" role="group" aria-label="Invite type">
        <button type="button" class="invite-kind-card${
          inviteKind === "family" || inviteKind === "grandparent" ? " is-selected" : ""
        }" data-invite-kind="family">
          <span class="invite-kind-copy">
            <strong>Sister, brother, or in-law</strong>
            <small>Another parent joins this Pod — then they add their kids</small>
          </span>
        </button>
        <button type="button" class="invite-kind-card${
          inviteKind === "friend" ? " is-selected" : ""
        }" data-invite-kind="friend" ${kids.length ? "" : "disabled"}>
          <span class="invite-kind-copy">
            <strong>Friend’s parent</strong>
            <small>One child’s Circle (not your Pod)</small>
          </span>
        </button>
      </div>
      <div id="invite-friend-kid-wrap" class="${inviteKind === "friend" && kids.length ? "" : "hidden"}">
        <label for="invite-friend-kid">Which kid’s Circle?</label>
        <select id="invite-friend-kid">${kidOpts || `<option value="">Add a kid first</option>`}</select>
      </div>
      ${
        !kids.length
          ? `<p class="tiny ata-lan-warn">Add a kid under Kids before inviting a friend.</p>`
          : ""
      }
      <p class="invite-share-lede">Share the code or QR. After they join, <strong>both of you</strong> approve — then kids can call.</p>
      <div class="invite-qr" id="invite-qr" role="img" aria-label="QR code for invite link" hidden></div>
      <p class="tiny center invite-qr-hint" id="invite-qr-hint" hidden>Scan with the other phone, across the table</p>
      <div class="code-box glow" id="code">······</div>
      <p class="tiny center" id="url"></p>
      <p class="flash-banner warn hidden" id="share-warn">This link only works on your home Wi‑Fi. Share from the PhoneHome app when you’re on the internet instead.</p>
      <div class="btn-row invite-share-row">
        <button type="button" class="primary" id="share">Share invite</button>
        <button type="button" class="ghost" id="copy">Copy link</button>
      </div>
      <button type="button" class="linkish" id="refresh-inv">Make a new code</button>
    </div>
    <div class="sheet tip-sheet">
      <h2>What happens next</h2>
      <ol class="how-list" id="invite-next-steps">
        <li>They tap the link (or scan the QR) — PhoneHome opens on your Mothership</li>
        <li>They create an account or sign in — the invite finishes automatically</li>
        <li>You approve them in Requests — then kids can call</li>
      </ol>
    </div>
    <div class="sheet tip-sheet">
      <h2>Someone invited you?</h2>
      <p class="tiny">Already have an account? Type their 6-digit code here — you don’t need a new sign-in.</p>
      ${familyInviteCodeFormHtml({ idPrefix: "invite-page" })}
    </div>
    </div>
  `);
  document.getElementById("back").onclick = () => {
    state.screen = "home";
    render();
  };
  document.getElementById("invite-go-grandma")?.addEventListener("click", () => {
    void openParentPanel({ scrollTo: "gp-setup-form" });
  });

  function paintNextSteps() {
    const ol = document.getElementById("invite-next-steps");
    if (!ol) return;
    ol.innerHTML = `<li>They tap the link (or scan the QR) — PhoneHome opens on your Mothership</li>
           <li>They create an account or sign in — the invite finishes automatically</li>
           <li>You approve them in Requests — then kids can call</li>`;
  }

  async function loadInvite() {
    inviteKind = inviteKindFromState();
    const kidSel = document.getElementById("invite-friend-kid");
    friendKidId = kidSel?.value || friendKidId;
    state.inviteFriendKidId = friendKidId;
    const body =
      inviteKind === "friend"
        ? JSON.stringify({ kind: "friend", targetKidLineId: friendKidId })
        : JSON.stringify({ kind: "family" });
    const data = await api(`/api/households/${hh.id}/invites`, { method: "POST", body });
    // Prefer HTTPS page origin / configured public URL — never accidentally share LAN http://10.x
    const code = data.invite.code;
    let base = (data.publicBaseUrl || "").replace(/\/$/, "");
    if (!base || /^http:\/\/(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|127\.|localhost)/i.test(base)) {
      if (isSecureMicContext()) base = location.origin;
      else base = data.publicBaseUrl || location.origin;
    }
    if (isSecureMicContext() && location.protocol === "https:") {
      // If parent is already on the tunnel/HTTPS host, share that exact origin
      base = location.origin;
    }
    sharePayload = {
      ...data,
      shareUrl: data.shareUrl || `${base}/?invite=${code}`,
      shareText:
        data.shareText ||
        `Join our PhoneHome family phone. Open the link, then enter code ${code}. After that we each approve the other so the kids can call.`,
    };
    const codeEl = document.getElementById("code");
    const urlEl = document.getElementById("url");
    if (codeEl) codeEl.textContent = code;
    if (urlEl) urlEl.textContent = sharePayload.shareUrl;
    paintInviteQr("invite-qr", sharePayload.shareUrl);
    const hint = document.getElementById("invite-qr-hint");
    if (hint) hint.toggleAttribute("hidden", !document.getElementById("invite-qr")?.innerHTML);
    const warn = document.getElementById("share-warn");
    if (warn) {
      const insecure = /^http:/i.test(sharePayload.shareUrl);
      warn.classList.toggle("hidden", !insecure);
    }
  }

  function syncKindUi() {
    inviteKind = inviteKindFromState();
    document.getElementById("invite-friend-kid-wrap")?.classList.toggle(
      "hidden",
      inviteKind !== "friend" || !kids.length
    );
    document.querySelectorAll("[data-invite-kind]").forEach((card) => {
      card.classList.toggle("is-selected", card.getAttribute("data-invite-kind") === inviteKind);
    });
    paintNextSteps();
  }
  document.querySelectorAll("[data-invite-kind]").forEach((el) => {
    el.addEventListener("click", async () => {
      const raw = el.getAttribute("data-invite-kind");
      state.inviteKind = raw === "friend" ? "friend" : "family";
      syncKindUi();
      try {
        await loadInvite();
      } catch (e) {
        setFlash(e.message || "Could not create invite", "error");
      }
    });
  });
  document.getElementById("invite-friend-kid")?.addEventListener("change", async () => {
    try {
      await loadInvite();
    } catch (e) {
      setFlash(e.message || "Could not create invite", "error");
    }
  });

  async function ensureSharePayload() {
    if (sharePayload) return true;
    try {
      await loadInvite();
    } catch (e) {
      setFlash(e.message || "Could not create invite", "error");
      return false;
    }
    if (!sharePayload) {
      setFlash("Could not create invite", "error");
      return false;
    }
    return true;
  }

  async function finishInviteShare(flashMsg) {
    if (inviteKind === "family" || inviteKind === "friend") markFamilyInviteShared(true);
    setFlash(flashMsg, "ok");
    await openParentPanel({ scrollTo: "parent-requests" });
  }
  document.getElementById("copy").onclick = async () => {
    if (!(await ensureSharePayload())) return;
    const text = sharePayload.shareText || `${sharePayload.shareUrl}`;
    await navigator.clipboard.writeText(text);
    await finishInviteShare("Invite copied — when they join, approve them in Requests");
  };
  document.getElementById("share").onclick = async () => {
    // Avoid awaiting when the payload is ready — Cap/Safari need a sync user gesture for share.
    if (!sharePayload && !(await ensureSharePayload())) return;
    const text = sharePayload.shareText || `${sharePayload.shareUrl}`;
    try {
      const result = await sharePlainText({
        title: "PhoneHome invite",
        text,
        url: sharePayload.shareUrl || "",
      });
      if (result === "shared") {
        await finishInviteShare("Invite sent — when they join, approve them in Requests");
        return;
      }
      if (result === "aborted") return;
    } catch {
      /* fall through to copy */
    }
    await navigator.clipboard.writeText(text);
    await finishInviteShare("Invite copied — when they join, approve them in Requests");
  };
  document.getElementById("refresh-inv").onclick = async () => {
    try {
      await loadInvite();
    } catch (e) {
      setFlash(e.message || "Could not create invite", "error");
    }
  };
  bindFamilyInviteCodeForm("invite-page");
  try {
    await loadInvite();
  } catch (e) {
    setFlash(e.message || "Could not create invite", "error");
  }
}

function renderAddContact() {
  const hh = state.households[0];
  if (isKidExperience()) {
    setFlash("Only parents can approve contacts", "error");
    state.screen = "home";
    state.nav = "phone";
    render();
    return;
  }
  const already = new Set((hh?.allowlist || []).map((a) => a.target_line_id));
  // Directory is server-scoped to the viewer’s own circle — never co-members of a host circle.
  const mySphere = (hh?.spheres || []).find((s) => s.is_mine || s.id === hh?.my_sphere_id);
  const inMyCircle = new Set(mySphere?.member_line_ids || []);
  const others = state.directory.filter((d) => {
    if (d.household_id === hh.id || already.has(d.id)) return false;
    // Defense in depth: if sphere membership is available, require it.
    if (inMyCircle.size && !inMyCircle.has(d.id)) return false;
    return true;
  });
  const gp = isGrandparentExperience();
  setAppPage(`
    <div class="sheet gp-contacts-page">
      <div class="gp-contacts-head">
        <h2>${gp ? "Add someone" : "Approve for a Circle"}</h2>
        <button type="button" class="primary gp-done-btn" id="back">Done</button>
      </div>
      <p>${
        gp
          ? "These are people your family already connected. Tap a name, then tap Add to my phone."
          : "Only people already linked by <strong>invite</strong> show here."
      }</p>
      ${
        others.length
          ? `
        <div class="picker-list" id="picker">
          ${others
            .map(
              (d, i) => `
            <button type="button" class="picker-row ${i === 0 ? "selected" : ""}" data-id="${d.id}">
              ${avatarHtml(d.name, d.id, "md")}
              <span><strong>${friendlyPersonName(d.name)}</strong><small>${d.household_name}</small></span>
            </button>`
            )
            .join("")}
        </div>
        <label>Name on your phone</label>
        <input id="label" placeholder="e.g. Alex" value="${others[0] ? friendlyPersonName(others[0].name).replace(/"/g, "&quot;") : ""}" />
        ${
          gp
            ? ""
            : `<label class="check-row"><input type="checkbox" id="vip" /> VIP — can still ring during Quiet Time</label>`
        }
        <button class="primary" id="save" style="margin-top:12px;width:100%">${gp ? "Add to my phone" : "Add to my phone"}</button>`
          : `<div class="empty hero-empty">
              <strong>${gp ? "No one else to add" : "Nobody left to approve"}</strong>
              <p>${
                already.size
                  ? gp
                    ? "Everyone from your family is already on your phone."
                    : "Everyone who’s joined is already on your list."
                  : canInviteFamily()
                    ? "Send an invite first. When they join, they’ll show up here."
                    : gp
                      ? "Ask your son or daughter to add you first."
                      : "Ask a parent to invite family first."
              }</p>
              ${
                already.size
                  ? `<button class="primary" id="to-invite">${gp ? "Back to my family" : "Back to contacts"}</button>`
                  : canInviteFamily()
                    ? `<button class="primary" id="to-invite">Invite someone</button>`
                    : `<button class="primary" id="to-invite">${gp ? "Back to Phone" : "Back home"}</button>`
              }
            </div>`
      }
    </div>
  `);
  let selectedId = others[0]?.id || "";
  document.getElementById("back").onclick = () => {
    state.screen = "manage-contacts";
    render();
  };
  document.getElementById("to-invite")?.addEventListener("click", () => {
    if (already.size) state.screen = "manage-contacts";
    else if (canInviteFamily()) state.screen = "invite";
    else state.screen = "home";
    render();
  });
  document.querySelectorAll(".picker-row").forEach((row) => {
    row.onclick = () => {
      document.querySelectorAll(".picker-row").forEach((r) => r.classList.remove("selected"));
      row.classList.add("selected");
      selectedId = row.getAttribute("data-id");
      const d = others.find((x) => x.id === selectedId);
      if (d) document.getElementById("label").value = friendlyPersonName(d.name);
    };
  });
  document.getElementById("save")?.addEventListener("click", async () => {
    const selected = others.find((x) => x.id === selectedId);
    await api(`/api/households/${hh.id}/allowlist`, {
      method: "POST",
      body: JSON.stringify({
        targetLineId: selectedId,
        label:
          document.getElementById("label").value.trim() ||
          friendlyPersonName(selected?.name) ||
          "Friend",
        alwaysAllow: Boolean(document.getElementById("vip")?.checked),
      }),
    });
    setFlash(
      gp
        ? `Added ${document.getElementById("label").value.trim() || "them"}. If you cannot call yet, ask them to add you too.`
        : `Approved ${document.getElementById("label").value.trim() || "them"} — ask them to approve you too`,
      "ok"
    );
    state.screen = "manage-contacts";
    await refresh();
  });
}

function renderManageContacts() {
  const hh = state.households[0];
  if (isKidExperience()) {
    setFlash("Only parents can manage contacts", "error");
    state.screen = "home";
    state.nav = "phone";
    render();
    return;
  }
  // This child’s Circle — include contacts from co-parent Pods (e.g. North GPs for Alex)
  // even when they are not on this parent’s own allowlist yet.
  const kid = resolveCircleKidLine(hh);
  const contacts = kid ? contactsOnKidCircle(hh, kid) : contactsInMyCircle(hh);
  const pending = pendingApprovals(hh);
  const editing = contacts.find((c) => c.id === state.editContactId);
  const sph = mySphere(hh);
  const circleLabel = kid
    ? String(kid.child_label || kid.name || "this child").replace(/</g, "") + "’s Circle"
    : (sph?.name || "your circle").replace(/</g, "");
  const gp = isGrandparentExperience();
  const gpMenu = !gp && kid ? kidPadUsesGrandparentsMenu(hh, kid) : false;
  const contactDialCaption = (c) => {
    if (gp) return c.speed_dial ? `Button ${c.speed_dial} · ` : "";
    if (gpMenu && isGrandparentContact(c)) return "Grandparents menu · ";
    if (c.speed_dial) return `Dial ${c.speed_dial} · `;
    return "";
  };
  setAppPage(`
    <div class="sheet gp-contacts-page">
      <div class="gp-contacts-head">
        <h2>${gp ? "Your family" : "This child’s Circle"}</h2>
        <button type="button" class="primary gp-done-btn" id="back">Done</button>
      </div>
      ${
        gp
          ? `<p>Add people so you can call them. When you are finished, tap <strong>Done</strong> to go back to your phone.</p>`
          : `<p>People join this child’s Circle by invite — not a shared family directory. You approve them → they can appear on the kid’s pad. They approve you → <em>Ready to call</em>.</p>`
      }
    </div>
    ${
      pending.length
        ? `<div class="sheet">
        <h2>${gp ? "Waiting for your answer" : "Needs your approval"}</h2>
        <p>${gp ? "Tap <strong>Yes, add them</strong> so they show up on button 1." : "These people are already linked by invite — tap Approve to put them on the phone."}</p>
        <div class="manage-list">${pending
          .map(
            (d, idx) => `
          <div class="manage-row" style="--i:${Math.min(idx, 10)}">
            ${avatarHtml(friendlyPersonName(d.name), d.id, "md")}
            <div>
              <strong>${friendlyPersonName(d.name)}</strong>
              <small>${d.household_name}${friendOfKid(d.id) ? ` · ${friendOfKid(d.id).label}’s friend` : ""}</small>
            </div>
            <div class="btn-row tight approve-row">
              <button type="button" class="primary" data-approve="${d.id}" data-name="${friendlyPersonName(d.name).replace(/"/g, "&quot;")}">${gp ? "Yes, add them" : "Approve"}</button>
              <button type="button" class="ghost" data-decline="${d.id}" data-name="${friendlyPersonName(d.name).replace(/"/g, "&quot;")}">${gp ? "No" : "No thanks"}</button>
            </div>
          </div>`
          )
          .join("")}</div>
      </div>`
        : ""
    }
    <div class="sheet" style="margin-top:12px">
      <h2>${gp ? "On your phone" : `In ${circleLabel}`}</h2>
      ${gp ? `<p class="tiny">Tap a name to change how it appears, or remove someone.</p>` : `<p>Rename, speed dial 2–9, VIP, or remove from your circle.</p>`}
      <button class="ghost" id="add-new" style="margin-bottom:14px;width:100%">${gp ? "Add someone else from my family…" : "Approve someone already invited…"}</button>
      ${
        contacts.length
          ? `<div class="manage-list">${contacts
              .map((c, idx) => {
                const st = approvalStatus(c);
                return `
            <div class="manage-row" style="--i:${Math.min(idx, 10)}">
              ${avatarHtml(contactDisplayName(c), c.target_line_id, "md")}
              <div>
                <strong>${contactDisplayName(c)}</strong>
                <small>${
                  gp
                    ? `${contactDialCaption(c)}${st.label}`
                    : `${contactDialCaption(c)}${st.label}${c.always_allow ? " · VIP" : ""}${
                        friendOfKid(c.target_line_id) ? ` · ${friendOfKid(c.target_line_id).label}’s friend` : ""
                      }`
                }</small>
              </div>
              <button type="button" class="ghost" data-edit="${c.id}">${gp ? "Change" : "Edit"}</button>
            </div>`;
              })
              .join("")}</div>`
          : `<div class="empty">${
              pending.length
                ? gp
                  ? "Tap Yes, add them above to put them on your phone."
                  : "Approve someone above to put them on your phone."
                : canInviteFamily()
                  ? "Invite someone first, or type their code under Parent → Requests. When they join, approve them here."
                  : gp
                    ? "Ask your son or daughter to connect you, then come back here."
                    : "Ask a parent to invite you, then approve them here."
            }</div>`
      }
    </div>
    ${
      editing
        ? `<div class="sheet-modal" id="edit-contact-modal">
        <div class="sheet-modal-card" role="dialog" aria-labelledby="edit-contact-title">
          <h2 id="edit-contact-title">${gp ? "Change" : "Edit"} ${contactDisplayName(editing)}</h2>
          <label>${gp ? "Name on your phone" : "Name on the phone"}</label>
          <input id="edit-label" value="${contactDisplayName(editing).replace(/"/g, "&quot;")}" />
          ${
            gp
              ? ""
              : gpMenu && isGrandparentContact(editing)
                ? `<p class="tiny">On the phone they share the <strong>Grandparents</strong> button with the other grandparents — not their own dial number.</p>`
                : `<label>Speed dial (2–9, blank = none)</label>
          <input id="edit-dial" type="number" min="2" max="9" inputmode="numeric" value="${editing.speed_dial ?? ""}" />
          <label class="check-row"><input type="checkbox" id="edit-vip" ${editing.always_allow ? "checked" : ""} /> VIP — rings through Quiet Time</label>`
          }
          <div class="btn-row two">
            <button class="primary btn-block" id="save-edit">Save</button>
            <button class="ghost btn-block" id="cancel-edit">Cancel</button>
          </div>
          <button class="ghost btn-block" id="remove-from-circle" style="margin-top:10px">${gp ? "Remove from my list" : "Remove from my list"}</button>
          <button class="danger btn-block" id="remove-contact" style="margin-top:8px">${gp ? "Remove from this phone" : "Remove from this phone"}</button>
        </div>
      </div>`
        : ""
    }
  `);
  document.getElementById("back").onclick = () => {
    state.editContactId = null;
    state.screen = "home";
    state.nav = "phone";
    render();
  };
  document.getElementById("add-new").onclick = () => {
    state.editContactId = null;
    state.screen = "add-contact";
    render();
  };
  document.querySelectorAll("[data-approve]").forEach((btn) => {
    btn.onclick = async () => {
      const targetLineId = btn.getAttribute("data-approve");
      const label = btn.getAttribute("data-name") || "Friend";
      await api(`/api/households/${hh.id}/allowlist`, {
        method: "POST",
        body: JSON.stringify({ targetLineId, label }),
      });
      setFlash(
        gp
          ? `Added ${label}. If you cannot call yet, ask them to add you too.`
          : `Approved ${label} — ask them to approve you too`,
        "ok"
      );
      await refresh();
    };
  });
  document.querySelectorAll("[data-decline]").forEach((btn) => {
    btn.onclick = async () => {
      const targetLineId = btn.getAttribute("data-decline");
      const label = btn.getAttribute("data-name") || "them";
      try {
        await api(`/api/households/${hh.id}/allowlist/decline`, {
          method: "POST",
          body: JSON.stringify({ targetLineId }),
        });
        setFlash(
          gp ? `${label} was not added` : `Declined ${label} — they won’t show under Needs approval`,
          "ok"
        );
        await refresh();
      } catch (e) {
        setFlash(e.message || "Could not decline", "error");
        render();
      }
    };
  });
  document.querySelectorAll("[data-edit]").forEach((btn) => {
    btn.onclick = () => {
      state.editContactId = btn.getAttribute("data-edit");
      render();
    };
  });
  document.getElementById("cancel-edit")?.addEventListener("click", () => {
    state.editContactId = null;
    render();
  });
  document.getElementById("edit-contact-modal")?.addEventListener("click", (e) => {
    if (e.target.id === "edit-contact-modal") {
      state.editContactId = null;
      render();
    }
  });
  document.getElementById("save-edit")?.addEventListener("click", async () => {
    const dialEl = document.getElementById("edit-dial");
    const vipEl = document.getElementById("edit-vip");
    const body = {
      label: document.getElementById("edit-label").value.trim(),
    };
    if (dialEl) {
      const dialRaw = dialEl.value.trim();
      body.speed_dial = dialRaw === "" ? null : Number(dialRaw);
    }
    if (vipEl) body.always_allow = Boolean(vipEl.checked);
    try {
      const synthetic =
        String(editing.id || "").startsWith("pod-family-") ||
        String(editing.id || "").startsWith("aunt-uncle-") ||
        String(editing.id || "").startsWith("hh-gp-");
      if (synthetic && editing.target_line_id) {
        // Promote cousin / aunt-uncle onto the Pod book, then apply dial/VIP.
        const existing = (hh.allowlist || []).find((a) => a.target_line_id === editing.target_line_id);
        if (existing?.id) {
          await api(`/api/households/${hh.id}/allowlist/${existing.id}`, {
            method: "PATCH",
            body: JSON.stringify(body),
          });
        } else {
          await api(`/api/households/${hh.id}/allowlist`, {
            method: "POST",
            body: JSON.stringify({
              targetLineId: editing.target_line_id,
              label: body.label || contactDisplayName(editing),
              speedDial: body.speed_dial ?? null,
              favorite: true,
              alwaysAllow: Boolean(body.always_allow),
            }),
          });
        }
      } else {
        await api(`/api/households/${hh.id}/allowlist/${editing.id}`, {
          method: "PATCH",
          body: JSON.stringify(body),
        });
      }
      setFlash(gp ? "Saved" : "Contact updated", "ok");
      state.editContactId = null;
      await refresh();
    } catch (e) {
      setFlash(e.message || "Could not save contact", "error");
      render();
    }
  });
  document.getElementById("remove-from-circle")?.addEventListener("click", async () => {
    if (!editing?.target_line_id) return;
    if (
      !confirm(
        gp
          ? `Remove ${contactDisplayName(editing)} from your list?`
          : `Remove ${contactDisplayName(editing)} from ${circleLabel}? They stay in other parents’ circles.`
      )
    )
      return;
    try {
      await api(`/api/households/${hh.id}/spheres/mine/members/${editing.target_line_id}`, {
        method: "DELETE",
      });
      setFlash(gp ? "Removed" : "Removed from your circle", "ok");
      state.editContactId = null;
      await refresh();
    } catch (e) {
      setFlash(e.message || "Could not remove from circle", "error");
      render();
    }
  });
  document.getElementById("remove-contact")?.addEventListener("click", async () => {
    if (!confirm(`Remove ${contactDisplayName(editing)} from this household’s contacts? Kids won’t dial them from this phone.`)) return;
    await api(`/api/households/${hh.id}/allowlist/${editing.id}`, { method: "DELETE" });
    if (editing.target_line_id) {
      try {
        await api(`/api/households/${hh.id}/spheres/mine/members/${editing.target_line_id}`, {
          method: "DELETE",
        });
      } catch {
        /* circle unlink best-effort */
      }
    }
    setFlash("Removed — they can no longer be dialed from this phone", "ok");
    state.editContactId = null;
    await refresh();
  });
}

function renderLeaveMessage() {
  const hh = state.households[0];
  const toLineId = state.leaveFor?.toLineId;
  const contact = (hh?.allowlist || []).find((c) => c.target_line_id === toLineId);
  const name = contact ? contactDisplayName(contact) : friendlyPersonName(lineName(toLineId));
  let recorder = null;
  let chunks = [];
  let mime = "audio/webm";
  let timer = null;
  let seconds = 0;
  let stream = null;
  /** greeting | recording | ending */
  let phase = "greeting";
  let finishing = false;

  app.innerHTML = `
    <div class="leave-vm-screen">
      <div class="topbar">
        <button class="icon-btn" id="back" aria-label="Hang up">←</button>
        ${pageBrandHtml("Answering machine")}
        <span style="width:40px"></span>
      </div>
      <div class="leave-vm-body">
        <h2>${name}</h2>
        <p>${state.leaveFor?.hint || "No answer — leave a message after the beep."}</p>
        <p class="vm-rec-status" id="vm-status">Playing greeting…</p>
      </div>
      <div class="call-actions outbound">
        ${hangupButtonHtml("vm-hangup")}
      </div>
    </div>
  `;

  const statusEl = () => document.getElementById("vm-status");

  const cleanupStream = () => {
    if (timer) clearInterval(timer);
    timer = null;
    releaseRecorderMicRef(stream);
    stream = null;
  };

  const exitHome = () => {
    cleanupStream();
    try {
      recorder?.stop();
    } catch {}
    recorder = null;
    state.leaveFor = null;
    state.leaveVmMountedKey = null;
    state.nav = "phone";
    localStorage.setItem("kl_nav", "phone");
    state.screen = "home";
    render();
  };

  const stopToBlob = () =>
    new Promise((resolve) => {
      if (!recorder || recorder.state === "inactive") {
        cleanupStream();
        resolve(null);
        return;
      }
      const rec = recorder;
      rec.ondataavailable = (e) => {
        if (e.data?.size) chunks.push(e.data);
      };
      rec.onstop = () => {
        const blob = new Blob(chunks, { type: mime });
        cleanupStream();
        recorder = null;
        resolve(blob);
      };
      try {
        rec.stop();
      } catch {
        cleanupStream();
        recorder = null;
        resolve(null);
      }
    });

  const saveIfSpoke = async (blob) => {
    if (!blob || blob.size < 64 || seconds < 1) return false;
    const dataUrl = await blobToBase64(blob);
    await api("/api/voicemails", {
      method: "POST",
      body: JSON.stringify({
        fromLineId: state.activeLineId,
        toLineId,
        audioBase64: dataUrl,
        audioMime: mime,
      }),
    });
    setFlash(`Message left for ${name}`, "ok");
    return true;
  };

  const finish = async ({ save } = { save: true }) => {
    if (finishing) return;
    finishing = true;
    const wasRecording = phase === "recording";
    phase = "ending";
    // Notify peer, then hard-silence local speakers — caller must not hear the take.
    stopVmMonitor({ notifyPeer: true });
    silenceCallerSoftphoneAudio();
    if (wasRecording && save) {
      if (statusEl()) statusEl().textContent = "Saving…";
      try {
        const blob = await stopToBlob();
        await saveIfSpoke(blob);
      } catch (e) {
        setFlash(e.message || "Could not leave message", "error");
      }
    } else {
      cleanupStream();
      try {
        recorder?.stop();
      } catch {}
      recorder = null;
    }
    silenceCallerSoftphoneAudio();
    exitHome();
  };

  const startRecording = async () => {
    if (finishing || phase === "ending") return;
    try {
      // Call path already unlocked AudioContext; re-assert before mic/tones.
      await unlockAudioCtx();
      stream = await ensureMicStream();
      armMicForCall();
      if (finishing) {
        releaseRecorderMicRef(stream);
        stream = null;
        return;
      }
      chunks = [];
      mime = pickRecorderMime();
      recorder = new MediaRecorder(stream, { mimeType: mime });
      recorder.ondataavailable = (e) => {
        if (e.data?.size) chunks.push(e.data);
      };
      seconds = 0;
      phase = "recording";
      if (statusEl()) statusEl().textContent = "Recording… 0s";
      recorder.start();
      // Opt-in answering machine: stream live to recipient softphone if they enabled it.
      void startVmMonitorAsCaller(toLineId, stream);
      timer = setInterval(() => {
        if (finishing) return;
        seconds += 1;
        const left = VM_MAX_SECONDS - seconds;
        if (statusEl()) {
          statusEl().textContent =
            left <= 5
              ? `Recording… ${seconds}s — wrapping up`
              : `Recording… ${seconds}s`;
        }
        if (seconds >= VM_MAX_SECONDS) {
          void finish({ save: true });
        }
      }, 1000);
    } catch (e) {
      if (statusEl()) statusEl().textContent = e.message || "Mic unavailable — hang up to leave";
    }
  };

  document.getElementById("back").onclick = () => void finish({ save: true });
  document.getElementById("vm-hangup").onclick = () => void finish({ save: true });
  document.querySelector(".leave-vm-screen .home-brand-lockup")?.addEventListener("click", () => {
    void finish({ save: true });
  });

  // Auto: greeting → beep → record (Web Audio unlock from prior call gesture).
  // Custom and default both get the same post-OGM beep; hang up mid-greeting skips beep/record.
  const vmCancelled = () => finishing || phase === "ending";
  (async () => {
    if (statusEl()) statusEl().textContent = "Playing greeting…";
    await unlockAudioCtx();
    try {
      await playLineGreetingThenBeep(toLineId, { isCancelled: vmCancelled });
    } catch {
      /* still cue + record if greeting/autoplay failed (unless hung up) */
      if (!vmCancelled()) {
        try {
          await playVmRecordBeep();
        } catch {}
      }
    }
    if (vmCancelled()) return;
    await startRecording();
  })();
}


function renderSettings() {
  // Settings deep-link opens focused line profile (Parent stays in the dock).
  openProfilePanel();
}


/** Splash / tutorial / auth — no dock; drop the 96px dock pad so compositions aren't stretched. */
const GATE_SCREENS = new Set([
  "splash",
  "tutorial",
  "welcome",
  "returning",
  "register",
  "set-password",
  "host",
  "join",
  "invite",
  "mothership-url",
]);

function syncGateChrome() {
  const gate = GATE_SCREENS.has(state.screen) || !state.user;
  app.classList.toggle("gate-screen", gate);
  const operatorUi =
    state.screen === "host" &&
    isLocalMothershipOperatorUi() &&
    state.mothershipBootstrap?.initialized === false;
  document.documentElement.classList.toggle("mothership-operator-ui", operatorUi);
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.setAttribute("content", operatorUi ? "#e8f2ec" : "#0e1a15");
}

function dismissBootSplash() {
  if (!dismissBootSplash._native) {
    dismissBootSplash._native = true;
    try {
      void nativePlugin()?.hideLaunchCover?.()?.catch?.(() => {});
    } catch {
      /* older shells without the native cover */
    }
  }
  const el = document.getElementById("boot-splash");
  if (!el || el.classList.contains("is-leaving")) return;
  if (!document.documentElement.classList.contains("boot-splash-on")) {
    el.remove();
    return;
  }
  el.classList.add("is-leaving");
  const done = () => {
    el.remove();
    document.documentElement.classList.remove("boot-splash-on");
  };
  el.addEventListener("animationend", done, { once: true });
  window.setTimeout(done, 700);
}

function render() {
  if (!(state.screen === "boot" && render._booting)) dismissBootSplash();
  // Freeze home chrome while the softphone ring sheet is up — remounting #app
  // behind a translucent overlay read as the incoming sheet flickering.
  if (
    !hideInAppIncomingForNativeUi() &&
    (state.call?.status === "incoming" || state.group?.status === "incoming") &&
    document.getElementById("call-layer")
  ) {
    syncPhoneRoleChrome();
    syncGateChrome();
    syncPhoneHomeLock();
    paintToast();
    paintCallLayer();
    return;
  }
  // New screen / dock tab / profile line: start at the top so readers aren't dumped mid-page.
  const routeKey = `${state.screen}|${state.nav || ""}|${state.editLineId || state.activeLineId || ""}|${
    state.screen === "tutorial" ? state.tutorialIndex : ""
  }`;
  const routeChanged = render._routeKey !== routeKey;
  if (routeChanged) {
    render._routeKey = routeKey;
    scrollPageToTop();
  }
  syncPhoneRoleChrome();
  if (state.nav === "controls") captureAtaFormDraftFromDom();
  if (!(state.screen === "home" && (!state.nav || state.nav === "phone"))) {
    state.speedDialEditing = false;
    closeFamilyRoomPickerSheet();
  }
  if (state.screen === "splash") renderSplash();
  else if (state.screen === "mothership-url") renderMothershipUrlGate();
  else if (state.screen === "tutorial") renderTutorial();
  else if (state.screen === "setup") renderSetupChecklist();
  else if (state.screen === "welcome") renderWelcome();
  else if (state.screen === "returning" || state.screen === "login") renderReturning();
  else if (state.screen === "register") renderRegister();
  else if (state.screen === "set-password") renderSetPassword();
  else if (state.screen === "host") renderHost();
  else if (state.screen === "join") renderJoin();
  else if (state.screen === "boot" && render._booting) renderBootHold();
  else if (!state.user) renderWelcome();
  else if (state.screen === "invite") renderInvite();
  else if (state.screen === "add-contact") renderAddContact();
  else if (state.screen === "manage-contacts") renderManageContacts();
  else if (state.screen === "leave-message") {
    const key = String(state.leaveFor?.toLineId || "");
    // Idempotent: presence/refresh remounts used to restart “Please leave a message…”.
    if (!(state.leaveVmMountedKey === key && document.querySelector(".leave-vm-screen"))) {
      state.leaveVmMountedKey = key;
      renderLeaveMessage();
    }
  }
  else if (state.screen === "quiet") renderQuietHours();
  else if (state.screen === "mothership-admin") void renderMothershipAdmin();
  else if (state.screen === "profile") renderProfile();
  else if (state.screen === "settings") renderSettings();
  else renderHome();
  if (routeChanged) markRouteEnter();
  syncGateChrome();
  syncPhoneHomeLock();
  paintToast();
  paintCallLayer();
}

/** Entrance motion runs only on a real route change — presence/refresh re-renders stay still. */
function markRouteEnter() {
  app.classList.remove("route-enter");
  void app.offsetWidth;
  app.classList.add("route-enter");
  window.clearTimeout(markRouteEnter._timer);
  markRouteEnter._timer = window.setTimeout(() => app.classList.remove("route-enter"), 1200);
}

/** Capacitor + CallKit (iOS). No-op in Safari/PWA. */
function nativeCallKit() {
  return nativePlugin();
}

function isNativeIosShell() {
  try {
    if (window.Capacitor?.isNativePlatform?.() && window.Capacitor?.getPlatform?.() === "ios") {
      return true;
    }
  } catch {
    /* ignore */
  }
  try {
    return (
      document.documentElement.classList.contains("capacitor-native") &&
      document.documentElement.dataset.nativePlatform === "ios"
    );
  } catch {
    return false;
  }
}

function isNativeAndroidShell() {
  try {
    if (window.Capacitor?.isNativePlatform?.() && window.Capacitor?.getPlatform?.() === "android") {
      return true;
    }
  } catch {
    /* ignore */
  }
  try {
    return (
      document.documentElement.classList.contains("capacitor-native") &&
      document.documentElement.dataset.nativePlatform === "android"
    );
  } catch {
    return false;
  }
}

/** Cap iOS or Cap Android — the installed phone shell, not a browser tab. */
function isNativePhoneShell() {
  return isNativeIosShell() || isNativeAndroidShell();
}

/**
 * Inbound answer uses in-process WebRTC on both phone shells.
 * iOS needs it because WKWebView cannot join CallKit audio.
 * Android needs it so audio survives the WebView being frozen or discarded.
 */
function usesNativeCallMedia() {
  return isNativePhoneShell() && callKitOwnsUi();
}

function thisDeviceWord() {
  return isNativeAndroidShell() ? "phone" : "iPhone";
}

function deviceUnlockName(biometry) {
  if (biometry === "touch") return "Touch ID";
  if (biometry === "fingerprint") return "fingerprint";
  if (biometry === "passcode") return "device passcode";
  if (biometry === "optic") return "Optic ID";
  if (biometry === "face" && isNativeAndroidShell()) return "face unlock";
  if (isNativeAndroidShell()) return "biometrics";
  return "Face ID";
}

/** Lock-screen Answer is always on in the Cap iOS app (no parent toggle). */
function showIosCallKitSettings() {
  return false;
}

function iosCallKitToggleHtml(_inputId) {
  return "";
}

function bindIosCallKitToggle(_inputId) {
  /* no-op — CallKit required */
}

/** Push unread VM + unseen missed onto the iOS home-screen icon badge. */
async function syncIosAppBadge() {
  if (!isNativePhoneShell()) return;
  const kit = nativeCallKit();
  if (!kit?.setBadge) return;
  const count = iosAppBadgeCount();
  try {
    await kit.setBadge({ count });
  } catch (e) {
    console.warn("[ios] setBadge failed", e);
  }
}

let iosBadgeLifecycleArmed = false;
function armIosAppBadgeLifecycle() {
  if (iosBadgeLifecycleArmed || !isNativePhoneShell()) return;
  iosBadgeLifecycleArmed = true;
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) void syncIosAppBadge();
  });
  try {
    const CapApp = window.Capacitor?.Plugins?.App;
    CapApp?.addListener?.("appStateChange", (ev) => {
      if (ev?.isActive) void syncIosAppBadge();
    });
  } catch {
    /* App plugin optional */
  }
}

/**
 * Cap iOS only: release WKWebView mic when idle / background so CallKit+TCC
 * does not leave a zombie capture that requires Settings toggle.
 * Safari PWA keeps page-lifetime park between calls.
 */
let iosMicLifecycleArmed = false;
let iosViewportLifecycleArmed = false;

function armIosViewportLifecycle() {
  if (iosViewportLifecycleArmed || !isNativeAppShell()) return;
  iosViewportLifecycleArmed = true;
  const onForeground = () => {
    if (!pendingNativeViewportRepair.current) return;
    pendingNativeViewportRepair.current = false;
    // Defer past Cap/Safari transition so insets settle.
    setTimeout(() => repairNativeShellViewport(), 50);
    setTimeout(() => repairNativeShellViewport(), 300);
  };
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) onForeground();
  });
  try {
    const CapApp = window.Capacitor?.Plugins?.App;
    CapApp?.addListener?.("appStateChange", (ev) => {
      if (ev?.isActive) onForeground();
    });
  } catch {
    /* App plugin optional */
  }
}

/** True while a live Cap call owns media — never hard-release mid-handoff. */
function callKitHoldsMic() {
  if (callKitGate.answered || callKitGate.accepting || acceptCallInFlight) return true;
  if (state.group) {
    const gs = state.group.status;
    if (gs === "calling" || gs === "incoming" || gs === "connecting" || gs === "active") return true;
  }
  if (!state.call) return false;
  const st = state.call.status;
  return (
    st === "calling" ||
    st === "ringing" ||
    st === "connecting" ||
    st === "active" ||
    st === "incoming"
  );
}

function releaseIdleMicIfSafe(reason) {
  if (!isNativePhoneShell()) return;
  if (callKitHoldsMic()) return;
  if (!state.localStream) return;
  console.warn("[ios] hard-release mic —", reason);
  hardReleaseMicStream();
}

function armIosMicLifecycle() {
  if (iosMicLifecycleArmed || !isNativePhoneShell()) return;
  iosMicLifecycleArmed = true;

  const onBackground = () => releaseIdleMicIfSafe("background");
  const onForeground = () => {
    if (state.localStream && !micStreamUsable(state.localStream)) {
      console.warn("[ios] clearing zombie mic on foreground");
      hardReleaseMicStream();
    }
    // Phone Recents may open us without Cap listeners having run yet.
    void consumeNativePendingOutgoing("foreground");
    // Unlock / open app mid-CallKit: WKWebView gum starts working — hard-refresh uplink.
    if (isNativeIosShell() && callKitOwnsUi() && callKitGate.answered) {
      console.info("[ios] foreground during CallKit — uplink refresh");
      callKitGate.audioActive = true;
      armCallKitUplinkRetries("foreground");
      reportMediaStat(state.pc, "foreground");
      if (isPcAlive()) {
        void refreshCallKitUplinkMic("foreground", { soft: false }).then((ok) => {
          if (ok) remountRemoteAudioFromPc("foreground");
        });
      }
    }
  };

  document.addEventListener("visibilitychange", () => {
    if (document.hidden) onBackground();
    else onForeground();
  });
  window.addEventListener("pagehide", onBackground);
  try {
    const CapApp = window.Capacitor?.Plugins?.App;
    CapApp?.addListener?.("appStateChange", (ev) => {
      if (ev?.isActive === false) onBackground();
      else if (ev?.isActive) onForeground();
    });
  } catch {
    /* App plugin optional */
  }
}

let iosCallKitReady = false;
/**
 * CallKit ↔ softphone UI gate.
 * - ringing (incoming, not answered): system CallKit Answer/Decline owns chrome
 * - answered + app foreground: in-app overlay (mute/hold/end) — iOS drops full system UI
 * - locked / background: system green bar / Dynamic Island still applies
 * answered/audioActive also defer WebRTC until AVAudioSession is active.
 */
let callKitGate = {
  answered: false,
  audioActive: false,
  /** True when JS forced audioActive before native didActivate (risk of silent gum). */
  forcedAudio: false,
  accepting: false,
  /** System CallKit incoming UI already shown (PushKit and/or reportIncoming). */
  systemRinging: false,
  /** SDP answer was sent for the current CallKit call. */
  answerSent: false,
  /** call.accepted signaled — stops ATA ringback before SDP. */
  acceptedSignaled: false,
  /** App-process WebRTC owns media (CallKit inbound) — not WKWebView. */
  nativeMedia: false,
  /** Local CallKit hold received before JS rebuilt state.call. */
  pendingHeld: null,
  /** Hold signal waiting for the hub WebSocket to reopen. */
  pendingHoldSignal: null,
  /** Native CallKit's canonical answer/connect epoch, shared with the app timer. */
  connectedAtMs: 0,
  /** Outbound started from Phone Recents / Favorites (CXStartCallAction before placeCall). */
  fromRecents: false,
  /** Polls while Recents outbound has CallKit but no JS call yet. */
  recentsDialAttempts: 0,
  hangupSent: false,
  acceptRetryTimer: null,
  pollTimer: null,
};

/** End signaling survives a suspended WebView and a reconnect after native teardown. */
const sentCallKitHangupIds = new Set();
const requestedNativeEndCallIds = new Set();
let pendingCallKitEndSignal = null;

function normalizeCallKitHangup(raw = {}) {
  const callId = String(
    raw?.callId || state.call?.callId || state.pendingNativeCallId || ""
  ).trim();
  const fromLineId = String(
    raw?.fromLineId ||
      state.call?.fromLineId ||
      state.pendingNativeFromLineId ||
      state.activeLineId ||
      ""
  ).trim();
  let toLineId = String(
    raw?.toLineId || state.call?.toLineId || state.pendingNativeToLineId || ""
  ).trim();
  if (!toLineId && state.call) {
    toLineId =
      state.call.toLineId === state.activeLineId
        ? String(state.call.fromLineId || "")
        : String(state.call.toLineId || "");
  }
  const reason = String(raw?.reason || "").trim();
  const payload = {
    type: "call.hangup",
    contractVersion: CALL_LIFECYCLE_CONTRACT_VERSION,
    callId,
    fromLineId,
    toLineId: toLineId || undefined,
  };
  if (reason) payload.reason = reason;
  return payload;
}

function rememberCallKitHangup(callId) {
  if (!callId) return;
  sentCallKitHangupIds.add(callId);
  while (sentCallKitHangupIds.size > 32) {
    sentCallKitHangupIds.delete(sentCallKitHangupIds.values().next().value);
  }
}

function sendCallKitHangup(raw = {}) {
  const payload = normalizeCallKitHangup(raw);
  if (!payload.callId) return false;
  if (sentCallKitHangupIds.has(payload.callId)) return true;
  if (state.ws && state.ws.readyState === 1 && !state.wsReplaced) {
    try {
      state.ws.send(JSON.stringify(payload));
      rememberCallKitHangup(payload.callId);
      if (pendingCallKitEndSignal?.callId === payload.callId) pendingCallKitEndSignal = null;
      callKitGate.hangupSent = true;
      return true;
    } catch {}
  }
  // Capacitor retained events are consumed once delivered. Preserve the terminal
  // signal in JS as well until the hub socket welcomes this client again.
  pendingCallKitEndSignal = payload;
  if (state.wsReplaced) reconnectWs();
  else ensureWs();
  return false;
}

function flushPendingCallKitEndSignal() {
  if (!pendingCallKitEndSignal) return false;
  return sendCallKitHangup(pendingCallKitEndSignal);
}

/** Deduped late force — never force gum before ~2.5s (early setActive silence). */
let callKitForceAudioTimer = null;

/**
 * System CallKit Answer / PushKit VoIP — required for every Cap iOS install.
 * Always on (no parent opt-out). Alert APNs is only a hub fallback when no VoIP token yet.
 */
function callKitEnabled() {
  return true;
}

function persistCallKitFlag(_enabled) {
  try {
    // Never persist off — Lock-screen Answer is required.
    localStorage.setItem("kl_callkit", "1");
  } catch {
    /* ignore */
  }
}

/** If WKWebView wiped localStorage, keep CallKit on when native UserDefaults says so. */
async function syncCallKitFlagFromNative() {
  const kit = nativeCallKit();
  if (!kit?.isCallKitEnabled) return;
  try {
    const nativeOn = Boolean((await kit.isCallKitEnabled())?.enabled);
    let stored = "";
    try {
      stored = String(localStorage.getItem("kl_callkit") || "");
    } catch {
      stored = "";
    }
    if (!stored && nativeOn) persistCallKitFlag(true);
  } catch {
    /* older plugin */
  }
}

async function clearRegisteredVoipTokens() {
  if (!state.activeLineId || !state.sessionId) return;
  const path = isNativeAndroidShell() ? "/api/devices/fcm-token" : "/api/devices/voip-token";
  try {
    await api(path, {
      method: "DELETE",
      body: JSON.stringify({ lineId: state.activeLineId }),
    });
  } catch (e) {
    console.warn("[push] token clear failed", e);
  }
}

/** Keep CallKit/PushKit armed. Disable requests are ignored (product requirement). */
async function applyCallKitPreference(enabled) {
  if (!enabled) {
    console.info("[ios] ignore CallKit disable — Lock-screen Answer is required");
  }
  persistCallKitFlag(true);
  const kit = nativeCallKit();
  try {
    await kit?.setCallKitEnabled?.({ enabled: true });
  } catch (e) {
    console.warn("[ios] setCallKitEnabled", e);
  }
  try {
    await kit?.registerVoIP?.();
  } catch (e) {
    console.warn("[ios] registerVoIP", e);
  }
  void syncCallKitStateFromNative("enable");
  armCallKitStatePoll();
}

/** System call UI (iOS CallKit or Android Telecom) may own chrome. */
function callKitOwnsUi() {
  return callKitEnabled() && isNativePhoneShell() && Boolean(nativeCallKit());
}

/**
 * Hide in-app Answer/Decline while ringing. iOS CallKit owns that chrome.
 * Android self-managed Telecom often shows nothing over an open WebView — keep the in-app sheet.
 */
function hideInAppIncomingForNativeUi() {
  if (!callKitOwnsUi()) return false;
  if (isNativeAndroidShell() && !document.hidden) return false;
  return true;
}

function resetCallKitGate() {
  if (callKitGate.nativeMedia) {
    try {
      void nativeCallKit()?.endNativeCall?.();
    } catch {}
  }
  callKitGate.answered = false;
  callKitGate.audioActive = false;
  callKitGate.forcedAudio = false;
  callKitGate.accepting = false;
  callKitGate.systemRinging = false;
  callKitGate.answerSent = false;
  callKitGate.acceptedSignaled = false;
  callKitGate.nativeMedia = false;
  callKitGate.pendingHeld = null;
  callKitGate.pendingHoldSignal = null;
  callKitGate.connectedAtMs = 0;
  callKitGate.fromRecents = false;
  callKitGate.recentsDialAttempts = 0;
  callKitGate.hangupSent = false;
  acceptCallInFlight = false;
  if (callKitForceAudioTimer) {
    clearTimeout(callKitForceAudioTimer);
    callKitForceAudioTimer = null;
  }
  if (callKitGate.acceptRetryTimer) {
    clearInterval(callKitGate.acceptRetryTimer);
    callKitGate.acceptRetryTimer = null;
  }
  if (callKitGate.pollTimer) {
    clearInterval(callKitGate.pollTimer);
    callKitGate.pollTimer = null;
  }
  if (callKitUplinkRetryTimer) {
    clearInterval(callKitUplinkRetryTimer);
    callKitUplinkRetryTimer = null;
  }
  state.pendingNativeCallId = "";
  state.pendingNativeFromLineId = "";
  state.pendingNativeToLineId = "";
}

/** While CallKit shows an incoming/active call, poll native state (cold WebView / missed events). */
function armCallKitStatePoll() {
  if (callKitGate.pollTimer || !isNativePhoneShell()) return;
  let n = 0;
  callKitGate.pollTimer = setInterval(() => {
    n += 1;
    if (callKitGate.answerSent || n >= 40) {
      clearInterval(callKitGate.pollTimer);
      callKitGate.pollTimer = null;
      return;
    }
    if (!callKitGate.systemRinging && !callKitGate.answered) {
      clearInterval(callKitGate.pollTimer);
      callKitGate.pollTimer = null;
      return;
    }
    void syncCallKitStateFromNative("poll");
  }, 500);
}

function armCallKitAcceptRetries() {
  if (callKitGate.acceptRetryTimer) return;
  let n = 0;
  callKitGate.acceptRetryTimer = setInterval(() => {
    n += 1;
    // Native answered but didActivate lagged — only force after ~4.8s so we don't
    // start getUserMedia before CallKit owns AVAudioSession (silent audio).
    if (callKitGate.answered && !callKitGate.audioActive && n >= 12) {
      console.warn("[ios] CallKit accept retry forcing audioActive", n);
      callKitGate.audioActive = true;
      callKitGate.forcedAudio = true;
    }
    if (!callKitGate.answered || callKitGate.answerSent) {
      if (callKitGate.answerSent || !callKitGate.answered || n >= 40) {
        clearInterval(callKitGate.acceptRetryTimer);
        callKitGate.acceptRetryTimer = null;
      }
      return;
    }
    // Answered but no SDP yet — keep polling pending (do NOT bail on !state.call).
    // Skip inbound accept retries while we are the outbound caller.
    if (
      state.call?.fromLineId === state.activeLineId &&
      state.call?.status !== "incoming"
    ) {
      if (n >= 5) {
        clearInterval(callKitGate.acceptRetryTimer);
        callKitGate.acceptRetryTimer = null;
      }
      return;
    }
    console.info("[ios] CallKit accept retry", n, {
      hasCall: Boolean(state.call),
      hasSdp: Boolean(state.call?.sdp),
    });
    signalCallKitAccepted(`retry-${n}`);
    void acceptCallFromCallKit();
    if (n >= 40) {
      clearInterval(callKitGate.acceptRetryTimer);
      callKitGate.acceptRetryTimer = null;
    }
  }, 400);
}

/** Deduped late force — never force gum before ~4s (early setActive silence). */
function scheduleForceCallKitAudio(reason = "timeout", delayMs = 4000) {
  if (!callKitGate.answered || callKitGate.answerSent || callKitGate.audioActive) return;
  if (callKitForceAudioTimer) return;
  callKitForceAudioTimer = setTimeout(() => {
    callKitForceAudioTimer = null;
    forceCallKitAudioAndAccept(reason);
  }, delayMs);
}

function forceCallKitAudioAndAccept(reason = "timeout") {
  if (!callKitGate.answered || callKitGate.answerSent) return;
  if (!callKitGate.audioActive) {
    console.warn("[ios] forcing audioActive —", reason);
    callKitGate.audioActive = true;
    callKitGate.forcedAudio = true;
  }
  armCallKitAcceptRetries();
  void acceptCallFromCallKit();
}

async function syncCallKitStateFromNative(reason = "poll") {
  const kit = nativeCallKit();
  if (!kit?.getCallState || !isNativePhoneShell()) return false;
  try {
    const st = await kit.getCallState();
    const handle = String(st?.handle || "").trim();
    const isOutgoing = Boolean(st?.isOutgoing);
    console.info("[ios] CallKit state sync", reason, {
      answered: !!st?.answered,
      audioActive: !!st?.audioActive,
      ringing: !!st?.ringing,
      systemHasCall: !!st?.systemHasCall,
      isOutgoing,
      localHeld: !!st?.localHeld,
      handle: handle || null,
      callId: st?.callId || null,
    });
    if (st?.callId) state.pendingNativeCallId = String(st.callId);
    const connectedAtMs = Number(st?.connectedAtMs || 0);
    if (connectedAtMs > 0) {
      callKitGate.connectedAtMs = connectedAtMs;
      if (state.call || state.group) markCallConnected(connectedAtMs);
    }
    if (st?.systemHasCall || st?.ringing || st?.answered) {
      callKitGate.systemRinging = true;
      armCallKitStatePoll();
    }
    if (st?.answered) {
      callKitGate.answered = true;
      callKitGate.systemRinging = true;
    }
    if (st?.audioActive) {
      callKitGate.audioActive = true;
      callKitGate.forcedAudio = false;
    }
    if (
      st?.localHeld === true ||
      state.holdByLineId === state.activeLineId ||
      callKitGate.pendingHeld === true
    ) {
      applyNativeLocalHold(
        { onHold: Boolean(st.localHeld), callId: st?.callId || "" },
        `sync:${reason}`
      );
    }
    // Recents/Favorites outbound: dial the stored handle — do NOT treat as orphan.
    const pendingHandle = String(st?.pendingOutgoingHandle || "").trim();
    const dialHandle = (isOutgoing && handle.startsWith("line_") ? handle : "") || pendingHandle;
    if (
      dialHandle.startsWith("line_") &&
      dialHandle !== state.activeLineId &&
      !state.call &&
      !state.group
    ) {
      console.info("[ios] Recents redial (state sync) →", dialHandle, reason);
      dialFromCallKitHandle(dialHandle, `sync:${reason}`);
      return true;
    }
    // Never auto-end while CallKit is still ringing / connecting — VoIP wake
    // often has systemHasCall before state.call exists; killing it drops the
    // inbound ring and strand the system UI (and aborts caller voicemail).
    // Only clear a clearly stuck *answered* outbound Recents attempt that
    // never got a JS placeCall after several syncs.
    if (
      st?.systemHasCall &&
      !state.call &&
      !callKitGate.accepting &&
      isOutgoing &&
      callKitGate.fromRecents &&
      reason === "poll"
    ) {
      const n = Number(callKitGate.recentsDialAttempts || 0);
      callKitGate.recentsDialAttempts = n + 1;
      if (n >= 16) {
        console.warn("[ios] Recents dial stalled — ending CallKit", reason);
        try {
          await kit.endCall?.({});
        } catch {}
        resetCallKitGate();
        return false;
      }
    }
    // Do NOT force audioActive after 400ms — that races didActivate and silences WKWebView.
    // Arm a ~4s safety valve; prefer real audioActivated.
    if (st?.answered && !callKitGate.audioActive && !isOutgoing && !callKitGate.fromRecents) {
      scheduleForceCallKitAudio(`sync:${reason}`, 4000);
      armCallKitAcceptRetries();
    }
    if (callKitGate.answered && !isOutgoing && !callKitGate.fromRecents) {
      armCallKitAcceptRetries();
      if (callKitGate.audioActive) void acceptCallFromCallKit();
    }
    return Boolean(st?.answered);
  } catch (e) {
    console.warn("[ios] getCallState failed", e);
    return false;
  }
}

function kickRemoteAudio() {
  const audio = typeof remoteAudio === "function" ? remoteAudio() : document.getElementById("remote-audio");
  if (!audio) return;
  try {
    audio.autoplay = true;
    audio.setAttribute("playsinline", "");
    audio.setAttribute("webkit-playsinline", "true");
    audio.playsInline = true;
    if (shouldRelayWebCallAudio() && webCallRelay) {
      silenceDirectCallAudioForRelay();
      resumeWebCallRelay();
    } else {
      audio.muted = false;
      audio.volume = 1;
      const p = audio.play();
      if (p && typeof p.catch === "function") p.catch(() => {});
    }
  } catch {}
  if (!isNativeIosShell() && (state.group || (state.call && state.call.status !== "incoming"))) {
    applyPreferredCallAudio();
  }
}

/** After CallKit didActivate: remount remote tracks onto <audio> and play (lock-screen). */
function remountRemoteAudioFromPc(reason = "remount") {
  const pc = state.pc;
  const audio = typeof remoteAudio === "function" ? remoteAudio() : document.getElementById("remote-audio");
  if (!pc || !audio) return false;
  try {
    const tracks = (pc.getReceivers?.() || [])
      .map((r) => r.track)
      .filter((t) => t && t.kind === "audio" && t.readyState === "live");
    if (!tracks.length) {
      kickRemoteAudio();
      return false;
    }
    for (const t of tracks) {
      try {
        t.enabled = true;
      } catch {}
    }
    if (shouldRelayWebCallAudio()) {
      try {
        audio.pause();
        audio.srcObject = null;
      } catch {
        /* ignore */
      }
      for (const t of tracks) connectTrackToWebCallRelay(t);
    } else {
      audio.srcObject = new MediaStream(tracks);
      audio.muted = false;
      audio.volume = 1;
    }
    audio.autoplay = true;
    audio.setAttribute("playsinline", "");
    audio.setAttribute("webkit-playsinline", "true");
    kickRemoteAudio();
    reportMediaStat(pc, reason);
    return true;
  } catch (e) {
    console.warn("[ios] remountRemoteAudio failed", e);
    kickRemoteAudio();
    return false;
  }
}

/** Safe media path breadcrumbs → hub journal (no SDP / candidates / keys). */
function reportMediaStat(pc, reason) {
  if (!pc || !state.ws || state.ws.readyState !== 1) return;
  try {
    const senders = pc.getSenders?.() || [];
    const receivers = pc.getReceivers?.() || [];
    const liveSend = senders.filter((s) => s.track && s.track.readyState === "live" && s.track.enabled).length;
    const mutedSend = senders.filter((s) => s.track?.kind === "audio" && s.track.muted).length;
    const liveRecv = receivers.filter((r) => r.track && r.track.readyState === "live").length;
    const remoteEl = remoteAudio();
    const remoteTracks = remoteEl?.srcObject?.getAudioTracks?.()?.length || 0;
    const dirs = (pc.getTransceivers?.() || [])
      .map((t) => `${t.mid || "?"}:${t.direction || "?"}`)
      .join(",");
    const why = `${String(reason || "").slice(0, 28)}${mutedSend ? `|mut=${mutedSend}` : ""}`.slice(0, 40);
    state.ws.send(
      JSON.stringify({
        type: "call.media",
        callId: state.call?.callId || state.pendingNativeCallId || null,
        ice: pc.iceConnectionState || "",
        conn: pc.connectionState || "",
        senders: liveSend,
        receivers: liveRecv,
        remoteTracks,
        dirs,
        reason: why,
      })
    );
  } catch {}
}

/** Serialize pending-offer fetch so concurrent CallKit retries don't race. */
let pendingOfferFetch = null;

/**
 * Tell the bridge CallKit answered — stops FXS ringback before WebRTC SDP is ready.
 * Safe to call repeatedly; only one WS send per call.
 */
function signalCallKitAccepted(reason = "accept") {
  if (!callKitGate.answered || callKitGate.acceptedSignaled) return false;
  const callId = state.call?.callId || state.pendingNativeCallId;
  const fromLineId =
    state.call?.fromLineId || state.pendingNativeFromLineId || "";
  const toLineId =
    state.call?.toLineId || state.pendingNativeToLineId || state.activeLineId;
  if (!callId || !fromLineId || !toLineId) return false;
  if (!state.ws || state.ws.readyState !== 1 || state.wsReplaced) {
    // Reclaim socket so accepted / answer can leave.
    if (state.wsReplaced) reconnectWs();
    else ensureWs();
    return false;
  }
  callKitGate.acceptedSignaled = true;
  try {
    state.ws.send(
      JSON.stringify({
        type: "call.accepted",
        contractVersion: CALL_LIFECYCLE_CONTRACT_VERSION,
        callId: String(callId),
        fromLineId: String(fromLineId),
        toLineId: String(toLineId),
      })
    );
    console.info("[ios] call.accepted → stop ATA ringback", callId, reason);
    return true;
  } catch (e) {
    callKitGate.acceptedSignaled = false;
    console.warn("[ios] call.accepted send failed", e);
    return false;
  }
}

async function ensureIncomingOfferForCallKit() {
  if (state.call?.sdp) return true;
  if (!state.activeLineId) return false;
  if (pendingOfferFetch) return pendingOfferFetch;
  pendingOfferFetch = (async () => {
    try {
      if (state.call?.sdp) return true;
      const body = await api(`/api/calls/pending?lineId=${encodeURIComponent(state.activeLineId)}`);
      if (body?.offer?.sdp) {
        console.info("[ios] pending offer fetched", body.offer.callId);
        await onIncomingOffer({
          type: "call.offer",
          callId: body.offer.callId,
          fromLineId: body.offer.fromLineId,
          toLineId: body.offer.toLineId,
          sdp: body.offer.sdp,
        });
        return Boolean(state.call?.sdp);
      }
    } catch (e) {
      console.warn("[ios] pending offer fetch failed", e);
    }
    return false;
  })();
  try {
    return await pendingOfferFetch;
  } finally {
    pendingOfferFetch = null;
  }
}

async function acceptCallFromCallKit() {
  if (callKitGate.accepting || acceptCallInFlight) return;
  if (!callKitGate.answered) {
    console.info("[ios] accept gated", {
      answered: callKitGate.answered,
      audioActive: callKitGate.audioActive,
      answerSent: callKitGate.answerSent,
    });
    return;
  }
  // Outbound CallKit (we placed the call) — never run the inbound accept path.
  if (
    state.call?.fromLineId === state.activeLineId &&
    state.call?.status !== "incoming"
  ) {
    kickRemoteAudio();
    return;
  }
  // Prefer CallKit audio session, but do not block SDP answer on didActivate.
  // Waiting here left ATA→softphone at ice=new until the analog side hung up.
  if (!callKitGate.audioActive) {
    console.info("[ios] accept before audio session — answer-first", {
      answerSent: callKitGate.answerSent,
    });
    armCallKitAcceptRetries();
    // Still stop ATA ringback as soon as we have SDP ids — don't wait for didActivate.
    signalCallKitAccepted("pre-audio");
    // Fall through and send call.answer; mic attaches on audioActivated.
  }
  if (callKitGate.answerSent && (isPcAlive() || callKitGate.nativeMedia)) {
    if (callKitGate.nativeMedia || !isPcAlive()) {
      return;
    }
    // Legacy only: WKWebView PC still alive without native flag (should not happen).
    try {
      closeCurrentPc();
    } catch {}
    callKitGate.answerSent = false;
  }
  callKitGate.accepting = true;
  const watchdog = setTimeout(() => {
    if (callKitGate.accepting || acceptCallInFlight) {
      console.warn("[ios] accept watchdog — clearing stuck accept flags");
      callKitGate.accepting = false;
      acceptCallInFlight = false;
      try {
        closeCurrentPc();
      } catch {}
      armCallKitAcceptRetries();
    }
  }, 12000);
  try {
    if (state.wsReplaced) reconnectWs();
    else ensureWs();
    if (!(await ensureIncomingOfferForCallKit())) {
      console.warn("[ios] CallKit answer but no SDP yet — will retry");
      armCallKitAcceptRetries();
      return;
    }
    signalCallKitAccepted("have-offer");
    // CallKit inbound: never reuse/create WKWebView PC — app-process WebRTC only.
    if (callKitGate.answerSent && callKitGate.nativeMedia) {
      reportNativeMediaStat("accept-already-native", {
        ice: "connected",
        conn: "connected",
        senders: 1,
        receivers: 1,
      });
      return;
    }
    if (isPcAlive()) {
      // Stale WKWebView PC from a race — tear down before native answer.
      console.warn("[ios] CallKit closing WKWebView PC before native media");
      try {
        closeCurrentPc();
      } catch {}
    }
    if (state.call?.status !== "incoming" && state.call?.status !== "connecting") {
      state.call = { ...state.call, status: "incoming" };
    }
    const msg = state.call;
    if (!msg?.sdp) {
      console.warn("[ios] CallKit accept — no SDP after ensure");
      armCallKitAcceptRetries();
      return;
    }
    console.info("[ios] CallKit → native WebRTC", msg.callId);
    stopRing();
    state.call = { ...msg, status: "connecting" };
    state.speakerOn = false;
    state.audioRouteUserSet = false;
    applyPreferredCallAudio();
    paintCallLayer();
    await acceptCallViaNativeMedia(msg);
    armConnectWatch();
    reportNativeMediaStat("accept-done", { ice: "checking", conn: "connecting", senders: 1, receivers: 1 });
    paintCallLayer();
    applyPreferredCallAudio();
  } catch (e) {
    if (!isInvalidStateError(e)) console.warn("[ios] CallKit accept failed", e);
    // Keep CallKit up and retry — do not tear down on a single getUserMedia blip.
    armCallKitAcceptRetries();
  } finally {
    clearTimeout(watchdog);
    callKitGate.accepting = false;
  }
}

let lastIosApnsToken = "";
let lastIosVoipToken = "";

/** Receiving identity for alert APNs — server binds to personal lines only. */
function iosAlertPushLineId() {
  return iosVoipPushLineId();
}

/**
 * Request PushKit registration through this user's own receiving identity.
 * Browsing a managed child line must not move the parent's lock-screen token
 * onto the child softphone.
 */
function iosVoipPushLineId() {
  const uid = state.user?.id;
  if (!uid) return state.activeLineId || "";
  const lines = (state.households || []).flatMap((hh) => hh?.lines || []);
  const direct = lines.filter(
    (line) =>
      ((line.mode || "parent") !== "child" && line.owner_user_id === uid) ||
      line.child_user_id === uid
  );
  return (
    direct.find((line) => line.id === state.activeLineId)?.id ||
    direct[0]?.id ||
    state.activeLineId ||
    ""
  );
}

async function registerIosApnsToken(token) {
  const t = String(token || lastIosApnsToken || "").trim();
  const lineId = iosAlertPushLineId();
  if (!t || !lineId || !state.sessionId) return;
  lastIosApnsToken = t;
  try {
    const data = await api("/api/devices/apns-token", {
      method: "POST",
      body: JSON.stringify({ lineId, apnsToken: t, platform: "ios" }),
    });
    console.info("[ios] APNs alert token registered", data.lineIds || data.lineId);
  } catch (e) {
    console.warn("[ios] APNs token register failed", e);
  }
}

async function registerIosVoipToken(token) {
  const t = String(token || lastIosVoipToken || "").trim();
  const lineId = iosVoipPushLineId();
  if (!t || !lineId || !state.sessionId) return;
  lastIosVoipToken = t;
  try {
    await api("/api/devices/voip-token", {
      method: "POST",
      body: JSON.stringify({ lineId, voipToken: t, platform: "ios" }),
    });
    console.info("[ios] VoIP token registered", lineId);
  } catch (e) {
    console.warn("[ios] VoIP token register failed", e);
  }
}

async function registerAndroidFcmToken(token) {
  const t = String(token || lastIosVoipToken || "").trim();
  const lineId = iosVoipPushLineId();
  if (!t || !lineId || !state.sessionId) return;
  lastIosVoipToken = t;
  try {
    await api("/api/devices/fcm-token", {
      method: "POST",
      body: JSON.stringify({ lineId, fcmToken: t, platform: "android" }),
    });
    console.info("[android] FCM token registered", lineId);
  } catch (e) {
    console.warn("[android] FCM token register failed", e);
  }
}

/** Sticky ids from alert/VoIP push so pending offer fetch + softphone UI can bind. */
function applyNativeIncomingHint(ev) {
  const pushId = ev?.callId ? String(ev.callId) : "";
  if (ev?.callId) state.pendingNativeCallId = pushId;
  if (ev?.fromLineId) state.pendingNativeFromLineId = String(ev.fromLineId);
  if (ev?.toLineId) state.pendingNativeToLineId = String(ev.toLineId);
  else if (state.activeLineId) state.pendingNativeToLineId = String(state.activeLineId);
}

/**
 * Alert APNs / notification tap: open softphone ring card (no CallKit).
 * Pull pending SDP if WS offer has not arrived yet.
 */
async function handleIncomingAlertPush(ev) {
  applyNativeIncomingHint(ev);
  state.wsReplaced = false;
  ensureWs();
  console.info("[ios] incomingAlert", ev?.source || "", ev?.callId || "");
  try {
    await ensureIncomingOfferForCallKit();
  } catch (e) {
    console.warn("[ios] pending offer on alert failed", e);
  }
  paintCallLayer();
}

async function bootIosCallKit() {
  const kit = nativeCallKit();
  if (!kit || !isNativePhoneShell() || iosCallKitReady) return;
  iosCallKitReady = true;
  try {
    // Force Lock-screen Answer on for every install (including prior explicit "0").
    try {
      persistCallKitFlag(true);
      localStorage.setItem("kl_callkit_default_on_v1", "1");
      localStorage.setItem("kl_callkit_required_v2", "1");
      await kit.setCallKitEnabled?.({ enabled: true });
    } catch {
      /* ignore */
    }
    await syncCallKitFlagFromNative();
    // Persist ON → native UserDefaults so the *next* killed-app launch
    // starts PushKit in attach() before any VoIP push arrives.
    try {
      await kit.setCallKitEnabled?.({ enabled: true });
    } catch (e) {
      console.warn("[ios] setCallKitEnabled", e);
    }

    // Always register both listener families. Toggling CallKit later only
    // starts/stops PushKit — adding listeners twice would duplicate events.
    await kit.addListener("apnsToken", async (ev) => {
      await registerIosApnsToken(String(ev?.token || ""));
    });
    await kit.addListener("incomingAlert", async (ev) => {
      if (callKitEnabled()) return;
      await handleIncomingAlertPush(ev);
    });
    await kit.addListener("voicemailAlert", async (ev) => {
      console.info("[ios] voicemailAlert", ev?.source || "", ev?.fromLabel || "");
      const who = String(ev?.fromLabel || "").trim();
      if (who) setFlash(`${who} left a message`, "info");
      state.nav = "voicemail";
      if (state.screen !== "leave-message" && !state.call && !state.group) {
        state.screen = "home";
      }
      try {
        await refresh();
      } catch {}
      render();
      void syncIosAppBadge();
    });
    // Register answer/audio BEFORE incomingPush so retained CallKit answer is not
    // wiped by a later incomingPush handler (retain queue is per-event, FIFO per addListener).
    await kit.addListener("callAnswered", async (ev) => {
      if (!callKitEnabled()) return;
      callKitGate.answered = true;
      callKitGate.systemRinging = true;
      if (ev?.nativeMedia) callKitGate.nativeMedia = true;
      applyNativeIncomingHint(ev);
      callKitGate.connectedAtMs = Number(ev?.connectedAtMs || ev?.ts || Date.now());
      if (state.call || state.group) markCallConnected(callKitGate.connectedAtMs);
      // Lock-screen Answer must reclaim signaling even if a prior tab marked replaced.
      if (state.wsReplaced) reconnectWs();
      else ensureWs();
      paintCallLayer();
      console.info("[ios] callAnswered", ev?.replay ? "(replay)" : "", ev?.callId || "", ev?.nativeMedia ? "native" : "");
      // Stop ATA ringback immediately from native/push ids. SDP retrieval remains
      // serialized below so native peer creation never races an empty offer.
      signalCallKitAccepted("callAnswered-immediate");
      const pendingOffer = ensureIncomingOfferForCallKit();
      armCallKitAcceptRetries();
      armCallKitStatePoll();
      // Native WebRTC — do not arm WKWebView uplink retries.
      if (isNativeIosShell() && !callKitGate.nativeMedia && !ev?.nativeMedia) {
        armCallKitUplinkRetries("callAnswered");
      }
      // Await SDP before accept — fire-and-forget raced accept with empty state.call.
      try {
        await pendingOffer;
      } catch (e) {
        console.warn("[ios] pending offer on answer failed", e);
      }
      signalCallKitAccepted("callAnswered");
      void acceptCallFromCallKit();
      // Prefer real didActivate — force only after ~4s (silent if we gum too early).
      scheduleForceCallKitAudio("callAnswered-timeout", 4000);
    });
    await kit.addListener("callHeld", (ev) => {
      if (!callKitEnabled()) return;
      applyNativeLocalHold(ev, ev?.replay ? "event-replay" : "event");
    });
    await kit.addListener("audioActivated", async (ev) => {
      if (!callKitEnabled()) return;
      const wasForced = callKitGate.forcedAudio;
      const rekick = Boolean(ev?.rekick);
      const nativeAudio = Boolean(ev?.nativeMedia) || callKitGate.nativeMedia;
      callKitGate.audioActive = true;
      callKitGate.forcedAudio = false;
      if (callKitForceAudioTimer) {
        clearTimeout(callKitForceAudioTimer);
        callKitForceAudioTimer = null;
      }
      console.info(
        "[ios] CallKit audio session active",
        nativeAudio ? "(native WebRTC)" : "",
        wasForced ? "(after forced)" : "",
        rekick ? `(rekick ${ev?.delayMs || ""}ms)` : ""
      );
      if (nativeAudio) {
        // App-process WebRTC — do not touch WKWebView getUserMedia / <audio>.
        reportNativeMediaStat("native-didActivate", {
          ice: "connected",
          conn: "connected",
          senders: 1,
          receivers: 1,
        });
        armCallKitAcceptRetries();
        void acceptCallFromCallKit();
        return;
      }
      if (isNativeAndroidShell()) {
        remountRemoteAudioFromPc("audioActivated");
        [150, 400, 900, 1800].forEach((ms) =>
          setTimeout(() => remountRemoteAudioFromPc("audioActivated-kick"), ms)
        );
        setTimeout(() => applyPreferredCallAudio(), 900);
        armCallKitAcceptRetries();
        void acceptCallFromCallKit();
        return;
      }
      try {
        armMicForCall();
      } catch {}
      // Never await long getUserMedia inside this listener — lock-screen gum can
      // sit for 12s and block native audioActivated re-kicks from running.
      const kickMic = async () => {
        if (!rekick) await new Promise((r) => setTimeout(r, 280));
        if (!isPcAlive()) {
          armCallKitUplinkRetries("audioActivated-no-pc");
          return;
        }
        const needRefresh =
          rekick ||
          wasForced ||
          callKitGate.answerSent ||
          !micStreamSendingOk(state.localStream) ||
          !pcHasSendingMic(state.pc);
        try {
          if (needRefresh) {
            const why = rekick
              ? `didActivate-rekick-${ev?.delayMs || 0}`
              : wasForced
                ? "didActivate-after-forced"
                : "didActivate";
            await refreshCallKitUplinkMic(why, { soft: rekick && !wasForced });
          } else {
            await attachLocalMicToPc(state.pc, { force: true });
            reportMediaStat(state.pc, "audioActivated-mic");
          }
        } catch (e) {
          console.warn("[ios] audioActivated mic refresh", e);
        }
      };
      void kickMic();
      armCallKitUplinkRetries("audioActivated");
      try {
        for (const r of state.pc?.getReceivers?.() || []) {
          if (r.track) r.track.enabled = true;
        }
      } catch {}
      remountRemoteAudioFromPc("audioActivated");
      [150, 400, 900, 1800].forEach((ms) =>
        setTimeout(() => remountRemoteAudioFromPc("audioActivated-kick"), ms)
      );
      setTimeout(() => applyPreferredCallAudio(), 900);
      armCallKitAcceptRetries();
      void acceptCallFromCallKit();
    });

    // Native CallKit plugin calls this via WKWebView.evaluateJavaScript when Cap
    // notifyListeners cannot drain (lock-screen CallKit UI freezes the JS event loop).
    try {
      window.__phoneHomeCallKitDial = (payload = {}) => {
        const handle = String(payload?.handle || "").trim();
        console.info("[ios] native dial kick", handle || "(none)");
        if (handle) dialFromCallKitHandle(handle, "native-kick");
      };
      window.__phoneHomeCallKitHangup = (payload = {}) => {
        const callId = String(
          payload?.callId || state.call?.callId || state.pendingNativeCallId || ""
        ).trim();
        const fromLineId = String(
          payload?.fromLineId ||
            state.call?.fromLineId ||
            state.pendingNativeFromLineId ||
            state.activeLineId ||
            ""
        ).trim();
        let toLineId = String(
          payload?.toLineId || state.call?.toLineId || state.pendingNativeToLineId || ""
        ).trim();
        if (!toLineId && state.call) {
          toLineId =
            state.call.toLineId === state.activeLineId
              ? String(state.call.fromLineId || "")
              : String(state.call.toLineId || "");
        }
        let reason = String(payload?.reason || "").trim();
        if (
          !reason &&
          state.call &&
          state.call.toLineId === state.activeLineId &&
          (state.call.status === "incoming" ||
            state.call.status === "ringing" ||
            (callKitGate.systemRinging && !callKitGate.answerSent))
        ) {
          reason = "no-answer";
        }
        console.info("[ios] native hangup kick", callId || "(none)", reason || "");
        const signalSent = sendCallKitHangup({
          callId,
          fromLineId: fromLineId || state.activeLineId,
          toLineId: toLineId || undefined,
          reason,
        });
        if (state.call) {
          endCallUi(reason === "no-answer" ? "No answer" : "Call ended", {
            skipNativeEnd: true,
          });
        } else resetCallKitGate();
        callKitGate.hangupSent = signalSent;
      };
      window.__phoneHomeCallKitHeld = (payload = {}) => {
        applyNativeLocalHold(payload, "native-kick");
      };
      window.__phoneHomeCallKitKickMic = (reason = "native") => {
        if (!callKitEnabled()) return;
        // Inbound CallKit uses native WebRTC — ignore WKWebView mic kicks.
        if (callKitGate.nativeMedia || callKitGate.answered) {
          console.info("[ios] kickMic ignored (native CallKit)", reason);
          return;
        }
        const why = String(reason || "native").slice(0, 40);
        console.info("[ios] native kickMic", why);
        callKitGate.audioActive = true;
        callKitGate.forcedAudio = false;
        try {
          armMicForCall();
        } catch {}
        armCallKitUplinkRetries(`native-${why}`);
        reportMediaStat(state.pc, `kick-${why}`);
        if (!isPcAlive()) return;
        void refreshCallKitUplinkMic(`native-${why}`, { soft: true }).then((ok) => {
          if (ok) remountRemoteAudioFromPc(`native-${why}`);
        });
        remountRemoteAudioFromPc(`native-${why}`);
      };
    } catch {}
    await kit.addListener("audioDeactivated", (ev) => {
      // Native CallKit: mid-call didDeactivate is normal (route/BT); didActivate re-arms.
      if (ev?.nativeMedia || callKitGate.nativeMedia) {
        if (callKitGate.answered) return;
        callKitGate.audioActive = false;
        return;
      }
      // Ignore brief deactivations while a CallKit call is still answered —
      // clearing audioActive mid-call blocked remount / play kicks.
      if (callKitGate.answered || callKitHoldsMic()) return;
      callKitGate.audioActive = false;
      // Cap iOS: release capture when CallKit drops the session (prefer hard release over park).
      hardReleaseMicStream();
    });
    await kit.addListener("callStarted", (ev) => {
      if (!callKitEnabled()) return;
      // Outbound CXStartCallAction — system owns the call; keep mic.
      callKitGate.answered = true;
      callKitGate.systemRinging = true;
      if (ev?.callId) state.pendingNativeCallId = String(ev.callId);
      if (Number(ev?.connectedAtMs || 0) > 0) {
        callKitGate.connectedAtMs = Number(ev.connectedAtMs);
        if (state.call || state.group) markCallConnected(callKitGate.connectedAtMs);
      }
      const handle = String(ev?.handle || "").trim();
      console.info("[ios] callStarted (outbound CallKit)", ev?.callId || "", handle);
      if (ev?.fromRecents || handle.startsWith("line_")) {
        dialFromCallKitHandle(handle, ev?.fromRecents ? "callStarted-recents" : "callStarted");
      }
    });
    await kit.addListener("callConnected", (ev) => {
      if (!callKitEnabled()) return;
      const eventCallId = String(ev?.callId || "");
      const activeCallId = String(state.call?.callId || state.pendingNativeCallId || "");
      if (eventCallId && activeCallId && eventCallId !== activeCallId) return;
      callKitGate.connectedAtMs = Number(ev?.connectedAtMs || ev?.ts || Date.now());
      if (state.call || state.group) {
        markCallConnected(callKitGate.connectedAtMs);
        paintCallLayer();
      }
    });
    await kit.addListener("voipToken", async (ev) => {
      if (!callKitEnabled()) return;
      const token = String(ev?.token || "");
      if (isNativeAndroidShell()) await registerAndroidFcmToken(token);
      else await registerIosVoipToken(token);
    });
    await kit.addListener("voipTokenInvalid", async () => {
      lastIosVoipToken = "";
      await clearRegisteredVoipTokens();
    });
    await kit.addListener("incomingPush", async (ev) => {
      if (!callKitEnabled()) return;
      // Do NOT resetCallKitGate here — retained incomingPush can arrive after
      // callAnswered and would wipe answered/audioActive (lock-screen race).
      callKitGate.systemRinging = true;
      applyNativeIncomingHint(ev);
      const pushId = ev?.callId ? String(ev.callId) : "";
      // Only clear answerSent for a brand-new call id.
      if (pushId && state.call?.callId && pushId !== String(state.call.callId)) {
        callKitGate.answered = false;
        callKitGate.audioActive = false;
        callKitGate.forcedAudio = false;
        callKitGate.answerSent = false;
        callKitGate.acceptedSignaled = false;
      }
      state.wsReplaced = false;
      ensureWs();
      console.info("[ios] incomingPush", pushId || "");
      armCallKitStatePoll();
      void syncCallKitStateFromNative("incomingPush");
      // Warm the existing authenticated ICE endpoint while the phone is ringing.
      // The result stays memory-only; native Answer reuses the same in-flight promise.
      void iceServers();
      // Start pulling SDP immediately — don't wait for answer gesture.
      void ensureIncomingOfferForCallKit();
      // If we already answered (replay race), stop ATA ringback with push line ids.
      if (callKitGate.answered) signalCallKitAccepted("incomingPush");
    });
    await kit.addListener("callEnded", (ev) => {
      if (!callKitEnabled() && !callKitGate.systemRinging && !callKitGate.answered) return;
      const nativeReason = String(ev?.reason || "").trim();
      const wasMissed =
        nativeReason === "no-answer" ||
        (ev?.answered !== true && callKitGate.systemRinging && !callKitGate.answered);
      const declineReason = wasMissed ? "no-answer" : nativeReason;
      const payload = normalizeCallKitHangup({
        callId: ev?.callId,
        fromLineId: ev?.fromLineId,
        toLineId: ev?.toLineId,
        reason: declineReason,
      });
      // nativeKickRequested means evaluateJavaScript was attempted, not delivered.
      // Only a recorded WS send suppresses replay; otherwise queue through welcome.
      sendCallKitHangup(payload);
      if (state.call) {
        endCallUi(wasMissed ? "Declined" : "Call ended", { skipNativeEnd: true });
      } else resetCallKitGate();
      if (answeredElsewhereCallIds.has(String(payload.callId || ""))) {
        void syncIosAppBadge();
      } else if (wasMissed) {
        state.pendingNativeMissed = Math.max(1, Number(state.pendingNativeMissed) || 0);
        void syncIosAppBadge();
        void refresh().then(() => syncIosAppBadge()).catch(() => {});
      } else {
        void syncIosAppBadge();
      }
    });
    await kit.addListener("nativeRemoteEnded", (ev) => {
      const endedCallId = String(ev?.callId || "").trim();
      const activeCallId = String(
        state.call?.callId || state.pendingNativeCallId || ""
      ).trim();
      // Retained native events can replay after another call has already begun.
      if (endedCallId && activeCallId && endedCallId !== activeCallId) {
        console.info("[ios] ignore stale native remote end", endedCallId);
        return;
      }
      console.info(
        "[ios] native remote ended",
        endedCallId || "(none)",
        String(ev?.connectionState || "")
      );
      // The bridge/server already owns the first terminal result. This event is
      // local UI recovery only and must not send another call.hangup.
      if (state.call) {
        endCallUi("Call ended", { skipNativeEnd: true });
      } else {
        resetCallKitGate();
      }
      void syncIosAppBadge();
    });

    try {
      const res = await kit.registerAlertPush?.();
      console.info("[ios] alert push permission", res?.granted);
    } catch (e) {
      console.warn("[ios] registerAlertPush failed", e);
    }
    try {
      await kit.registerVoIP();
    } catch (e) {
      console.warn("[ios] registerVoIP failed", e);
    }
    try {
      await kit.requestBadgePermission?.();
    } catch (e) {
      console.warn("[ios] badge permission", e);
    }
    armIosAppBadgeLifecycle();
    armIosMicLifecycle();
    armIosViewportLifecycle();
    void syncIosAppBadge();
    void syncCallKitStateFromNative("boot");
    void consumeNativePendingOutgoing("boot");
    setTimeout(() => void consumeNativePendingOutgoing("boot-1s"), 1000);
    setTimeout(() => void consumeNativePendingOutgoing("boot-3s"), 3000);
    // Clear stranded CallKit UI (hub hangup race / failed Recents) once offer/dial had time.
    setTimeout(() => {
      void (async () => {
        if (state.call || callKitGate.accepting) return;
        const kit2 = nativeCallKit();
        if (!kit2?.getCallState) return;
        try {
          const st = await kit2.getCallState();
          if (!st?.systemHasCall) return;
          // Live inbound ring: pending offer usually lands <2s; Recents dial may take longer.
          if (callKitGate.fromRecents && Number(callKitGate.recentsDialAttempts || 0) < 20) return;
          console.warn("[ios] stranded CallKit after boot — ending");
          await kit2.endCall?.({});
          resetCallKitGate();
        } catch {}
      })();
    }, callKitGate.fromRecents ? 20000 : 8000);

    armCallKitStatePoll();
    console.info("[ios] CallKit / PushKit armed (required)");
  } catch (e) {
    console.warn("[ios] CallKit boot failed", e);
    iosCallKitReady = false;
  }
}

async function boot() {
  await ensurePublicHttps();
  armWebUpdateDetection();
  // Native shell: mark early so CSS can avoid double safe-area / dvh WebView quirks.
  try {
    if (window.Capacitor?.isNativePlatform?.()) {
      document.documentElement.classList.add("capacitor-native");
      document.documentElement.classList.add("ph-standalone");
      document.documentElement.dataset.nativePlatform = window.Capacitor.getPlatform?.() || "native";
    }
  } catch {}
  initSpecularTilt();
  await applyNativeOnboardingFlags();
  try {
    state.migrateTransfer = await loadMigrateTransfer();
  } catch {
    state.migrateTransfer = null;
  }
  capturePendingFamilyInviteFromUrl();
  mountIosAppBanner();
  await offerIosAppHandoff();
  await loadMothershipBootstrap();

  // Fresh self-hosted Mothership (local dashboard / Mac app) — operator claim, not phone tour.
  if (
    state.mothershipBootstrap &&
    state.mothershipBootstrap.initialized === false &&
    isLocalMothershipOperatorUi() &&
    !state.sessionId
  ) {
    state.mode = "host";
    state.screen = "host";
    render();
    return;
  }

  if (isNativeAppShell()) {
    bindNativeInviteLinkListener();
    const inviteLink = await consumeNativeInviteLink();
    if (inviteLink && (await handleNativeInviteLink(inviteLink))) {
      void loadAppStorefront();
      return;
    }
    const hub = await ensureMothershipUrlReady();
    if (hub === "reloading") return;
    if (hub === "gate") {
      state.mothershipUrlChanging = false;
      const saved = await getSavedMothershipUrl();
      state.mothershipUrlDraft =
        saved || (location.protocol === "https:" && !isBundledCapOrigin() ? location.origin : "") || "";
      state.pendingMothershipConnect = true;
      // New installs: PhoneHome splash + short How it works before Mothership Connect.
      if (!saved && isBundledCapOrigin()) {
        state.mothershipUrlFromOnboarding = false;
        state.screen = "splash";
        render();
        return;
      }
      if (mustCompleteHowItWorks()) {
        state.mothershipUrlFromOnboarding = false;
        state.screen = "splash";
        render();
        return;
      }
      state.mothershipUrlFromOnboarding = false;
      state.screen = "mothership-url";
      render();
      return;
    }
  }

  await restoreNativeSession();
  await syncCallKitFlagFromNative();

  // One-tap Grandma link — claim before restoring any other auth path.
  if (!state.sessionId && loadPendingGrandparentSetupToken()) {
    try {
      await redeemPendingGrandparentSetup();
      if (mustCompleteHowItWorks()) startForcedHowItWorks();
      await refresh();
      void persistSession(state.sessionId);
      render();
      void bootIosCallKit();
      return;
    } catch (e) {
      setPendingGrandparentSetupToken("");
      setFlash(e.message || "That setup link didn’t work — ask for a new one", "error");
    }
  }

  if (state.sessionId) {
    try {
      if (mustCompleteHowItWorks()) startForcedHowItWorks();
      await refresh();
      void persistSession(state.sessionId);
      if (mustCompleteHowItWorks()) {
        startForcedHowItWorks();
      }
      render();
      void bootIosCallKit();
      return;
    } catch (e) {
      if (isUnauthorizedError(e)) {
        await persistSession("");
        localStorage.removeItem("kl_line");
      }
    }
  }
  const invite = loadPendingFamilyInvite();
  const guardianCode = new URLSearchParams(location.search).get("guardian");
  // Invite deep-links skip splash but still offer tutorial if never seen
  if (loadPendingJoinToken() || invite) {
    state.mode = "join";
    if (invite) setPendingFamilyInvite(invite);
    void peekPendingJoinToken();
    if (mustCompleteHowItWorks()) {
      startForcedHowItWorks();
    } else if (localStorage.getItem(TUTORIAL_KEY) === "1") {
      state.screen = "join";
    } else {
      state.tutorialIndex = 0;
      state.tutorialFarthest = 0;
      state.screen = "tutorial";
    }
  } else if (guardianCode && state.sessionId) {
    state.pendingGuardianCode = guardianCode;
    if (mustCompleteHowItWorks()) {
      startForcedHowItWorks();
    } else {
      state.screen = "home";
      state.nav = "controls";
      localStorage.setItem("kl_nav", "controls");
    }
  } else if (guardianCode) {
    state.pendingGuardianCode = guardianCode;
    if (mustCompleteHowItWorks()) startForcedHowItWorks();
    else state.screen = "login";
  } else if (hasCompletedHowItWorksInstall() || localStorage.getItem(TUTORIAL_KEY) === "1") {
    // Native already ran How it works before Connect — land on Sign in / Welcome.
    state.screen = "welcome";
  } else {
    state.screen = "splash";
  }
  render();
  if (state.pendingGuardianCode && state.sessionId) {
    try {
      if (hasMemberPod()) {
        await redeemPendingGuardianInvite();
      } else if (!mustCompleteHowItWorks()) {
        state.screen = "join";
        setFlash("Name your family to finish the co-parent invite", "ok");
        render();
      }
    } catch (e) {
      setFlash(e.message || "Could not accept guardian invite", "error");
      render();
    }
  }
}

function renderBootHold() {
  const app = document.getElementById("app");
  if (app && !app.querySelector(".boot-hold")) {
    app.innerHTML = `<div class="boot-hold" aria-busy="true"></div>`;
  }
}

// Still "boot" after a clean return means the shell is reloading onto the
// saved Mothership — keep holding blank instead of flashing Sign in.
boot().then(
  () => {
    if (state.screen !== "boot") render._booting = false;
  },
  (err) => {
    render._booting = false;
    render();
    throw err;
  }
);
bindPullToRefresh();
